/* Question bank PA test (English convenience translation), Wft Mortgage Credit. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["hypothecair-krediet"] = [
["On which two measures does the lender test the maximum mortgage under the Temporary Mortgage Credit Regulation (TRHK)?", [["The financing burden relative to the test income and the loan-to-value ratio (LTV)", "The TRHK limits the mortgage both on the basis of the costs the consumer can bear and on the basis of the value of the home."], ["The net disposable income after tax and the consumer's total assets", "The TRHK works with a gross test income and financing burden percentages, not with net income or assets."], ["The WOZ value (municipal property valuation) of the home and the number of years the consumer has been continuously employed", "The WOZ value is not a main measure and employment is not a statutory lending standard; at most they are relevant for acceptance."], ["The purchase price of the home and the level of the NHG (National Mortgage Guarantee) cost limit", "The purchase price and the NHG limit do not determine the statutory lending standards; the TRHK looks at costs and the value of the home."]], "1a.2"],
["A client chooses a fixed-rate period of 20 years. Which interest rate is used to calculate the financing burden under the TRHK?", [["The actual debit interest rate stated in the offer for that fixed-rate period", "With a fixed-rate period of ten years or more, the interest rate risk is limited and the test is based on the actual interest rate."], ["The test rate set by the AFM, regardless of the fixed-rate period", "The AFM test rate is decisive only for a fixed-rate period shorter than ten years."], ["The average interest rate of the past five years for that fixed-rate period at this lender", "A historical average plays no role in the test; what counts is the interest rate of this loan."], ["The actual interest rate plus a fixed surcharge of two percentage points", "The TRHK has no fixed surcharge on the actual interest rate for long fixed-rate periods."]], "1a.2"],
["A client chooses a fixed-rate period of 5 years. The interest rate in the offer is higher than the current AFM test rate. Which interest rate is used for the test?", [["The offer rate, because for short fixed-rate periods the higher of the two applies", "For a fixed-rate period shorter than ten years, the higher of the actual interest rate and the test rate applies; here that is the offer rate."], ["The AFM test rate, because it always applies for fixed-rate periods shorter than ten years", "The test rate is a lower limit; if the actual interest rate is higher, the actual rate is used."], ["The average of the offer rate and the AFM test rate", "Averaging the two rates is not the method; the higher of the two applies."], ["The lower of the two, because the client is entitled to that", "The test is meant to absorb interest rate risk; therefore the higher rate applies, not the lower."]], "1a.2"],
["Part of the requested mortgage is interest-only. How is this part in principle included in the financing burden under the TRHK?", [["As if it were repaid on an annuity basis over thirty years", "The financing burden is calculated on the basis of annuity repayment over thirty years, even for parts without a repayment obligation."], ["Only with the interest actually payable, without a repayment component", "Calculating with interest only would give too high a borrowing capacity; the TRHK assumes an annuity burden."], ["Not at all, because nothing is repaid during the term", "An interest-only part also entails costs and therefore counts in the test."], ["As if it were repaid linearly over twenty years", "The TRHK does not calculate with linear repayment over twenty years but with an annuity over thirty years."]], "1a.2"],
["What does a widow's declaration (also called a partner declaration; weduweverklaring) record for a mortgage with a pledged insurance policy?", [["That the partner consents to the pledge or beneficiary designation of the policy in favour of the lender", "Through the declaration the partner cannot later assert rights to the payout that take priority over repayment of the loan."], ["That after the client's death the partner automatically takes over the mortgage with the insurance payout", "A declaration does not make the partner a debtor; a takeover requires its own assessment by the lender."], ["That the partner is entitled to a survivor's pension from the employer", "A survivor's pension follows from the pension scheme rules, not from a declaration attached to the mortgage."], ["That the partner waives her right to an Anw benefit (surviving dependants benefit) in favour of the bank", "An Anw benefit is a personal right of the surviving dependant and cannot be transferred to the bank."]], "1b.8"],
["Why does the TRHK calculate with gross housing costs (interest and repayment before tax) and not with net costs?", [["Because the interest deduction's tax effect is already built into the percentages", "The tables take the tax burden and the deduction into account, so the test is carried out on gross costs."], ["Because mortgage interest has no longer been deductible since 2013", "Mortgage interest on an owner-occupied home debt is still deductible, provided the conditions are met."], ["Because under the GDPR (AVG) the lender may not take the client's tax benefit into account", "The lender may know and use tax information; the net effect is already included in the percentages."], ["Because net costs are only definitively known after the first income tax return", "Net costs can be calculated well in advance; the reason is that the percentages are already tailored to gross costs."]], "1a.2"],
["A home stands on leasehold land for which ground rent (canon) is paid annually. How does the ground rent count towards the lending standards?", [["The ground rent counts as a fixed cost, alongside interest and repayment", "The TRHK counts leasehold ground rent among the annual costs, in addition to interest and repayment."], ["The ground rent is added to the value of the home for the LTV", "Ground rent is a cost and not a component of value; leasehold rather reduces the market value."], ["The ground rent is relevant only to the valuer and not to the lending standards", "Ground rent also affects affordability and is therefore part of the financing burden."], ["The ground rent increases the test income because it is tax-deductible", "Ground rent does not increase the test income; it is in fact an additional cost for the consumer."]], "1a.2"],
["What does 'explain' mean in the lending standards?", [["The lender may deviate responsibly, provided this is reasoned and documented", "The TRHK permits deviation if it is justified on the basis of the personal situation; the justification must be documented."], ["The adviser explains to the client in writing how the maximum mortgage was calculated", "Explaining to the client is good service, but 'explain' is the lender's power to deviate on reasoned grounds."], ["The client may deviate from the standards by signing a declaration", "The consumer cannot set the standards aside; the deviation is a responsible decision by the lender."], ["The AFM approves in advance every deviation from the lending standards", "The AFM does not approve individual files in advance; it supervises the use of explain after the fact."]], "1a.2"],
["Ellen (54) and Rob (56) have lived in their terraced house in Zwolle for twenty years and have a mortgage of €280,000. Last year, after a reorganisation, Rob started a lower-paid job, which has significantly reduced their joint income. Their fixed-rate period is almost over and another lender offers a lower interest rate. They want to refinance without increasing the loan, but at their current income €280,000 no longer fits within the lending standards. What is correct?", [["Through explain the lender may deviate: they refinance without an increase and their costs fall", "Refinancing without an increase where the costs fall is a recognised situation in which deviating from the lending standards can be justified, provided it is documented with reasons."], ["Refinancing is not permitted as long as their loan does not fit within the current lending standards", "There is no absolute ban; explain offers room precisely for this situation."], ["They must first repay the part above the new standard, from their own funds or with a gift", "A mandatory repayment is not required if deviating is justified and substantiated."], ["When refinancing, the lending standards apply only to the interest rate and not to the size of the existing loan", "The TRHK tests the entire loan; deviating from the standards is possible only through explain."]], "1a.2"],
["Lisa (29) works as a physiotherapist and wants to buy her first home, an apartment in Arnhem. The valuer sets the market value at €350,000; that is also the purchase price. The purchase costs come to €8,000 and she does not want to co-finance any energy-saving measures. Her income is more than sufficient for the financing burden. What is her maximum mortgage under the LTV standard?", [["€350,000; she must pay the €8,000 purchase costs from her own funds", "With an LTV of at most 100% of the market value, €350,000 is the maximum; purchase costs fall outside it."], ["€358,000, because purchase costs may always be co-financed", "Co-financing purchase costs above the market value does not fit within the 100% LTV standard."], ["€371,000, because for first-time buyers the LTV may be 106% of the market value", "An LTV above 100% applied only during the phase-down until 2018; there is no higher main rule for first-time buyers."], ["€342,000, because the purchase costs are first deducted from the market value", "The purchase costs do not reduce the permitted mortgage; they merely have to come from own funds."]], "1a.2"],
["A client borrows €315,000 on a home with a market value of €350,000. What is the loan-to-value (LTV)?", [["90%", "€315,000 divided by €350,000 is 0.90, so an LTV of 90%."], ["111%", "That is the inverse ratio (value divided by loan), not the LTV."], ["10%", "10% is the part of the home's value that is not financed, not the LTV."], ["85%", "85% of €350,000 is €297,500; the loan is higher, so the LTV is 90%."]], "1a.2"],
["What applies in the TRHK to consumers who have reached the AOW (state pension) age?", [["Separate financing burden percentages apply to them", "The TRHK contains separate tables for people entitled to the AOW (state pension), tailored to their different tax burden and expenditure."], ["They may no longer take out a new mortgage", "There is no age ban; a mortgage can be responsible even after the AOW (state pension) age."], ["A maximum LTV of 50% always applies to them", "The TRHK has no lower LTV limit based on age."], ["Their AOW (state pension) benefit does not count as test income", "AOW (state pension) and pension do count as income in the test."]], "1a.2"],
["For whom is the Code of Conduct for Mortgage Financing (Gedragscode Hypothecaire Financieringen, GHF) binding?", [["For lenders that have committed to the code through their trade association", "The GHF is self-regulation; it binds the participating providers, such as banks and insurers that subscribe to the code."], ["For every consumer who takes out a mortgage", "A code of conduct binds the parties that commit to it, not the consumer."], ["For all Dutch civil-law notaries when drawing up and executing mortgage deeds for consumers", "Notaries have their own professional rules; the GHF is aimed at lenders."], ["Only for mortgage advisers with an AFM licence", "The GHF was drawn up by and for lenders, not primarily for advisers."]], "1a.3"],
["A mortgage has a nominal interest rate of 4% per year, paid in twelve monthly instalments. What is correct about the effective annual interest rate?", [["Slightly higher than 4%, because interest is paid earlier in monthly instalments", "Because of monthly payment the interest works as compound interest; the effective annual rate comes to approximately 4.07%."], ["It is exactly 4%, because the interest is agreed per year", "The moment of payment affects the effective rate; paying monthly makes it slightly higher."], ["It is slightly lower than 4%, because the client also repays part of the loan each month", "Repayment reduces the amount of interest in euros, not the effective interest percentage."], ["It is 48%, because 4% is calculated twelve times a year", "Each month one twelfth of the annual rate is calculated, so approximately 0.33% per month."]], "1e.1"],
["What does the current Code of Conduct for Mortgage Financing mainly address?", [["Minimum requirements for the offer, the terms and the cost and interest information", "The GHF regulates, among other things, what an offer must contain and how the provider informs about terms and conditions, costs and interest."], ["The level of the financing burden percentages per income bracket and per test rate", "Those percentages are set out in the TRHK, not in the GHF."], ["The tax conditions for deducting mortgage interest", "The tax rules are laid down in the Income Tax Act 2001."], ["The conditions for forgiveness of a residual debt with NHG (National Mortgage Guarantee)", "Those conditions are set out in the NHG Terms and Conditions."]], "1a.3"],
["With an annuity mortgage at a constant interest rate, the net monthly costs rise over time. What is the cause?", [["The interest portion falls, so the interest deduction and thus the tax benefit decrease", "The gross annuity stays the same, but because the deductible interest portion falls, the net cost rises."], ["The lender raises the repayment portion every year according to a fixed schedule", "The repayment portion grows by itself within the same gross annuity; the gross cost does not rise."], ["The interest rate is automatically adjusted to inflation", "With a fixed interest rate there is no inflation adjustment."], ["The notional rental value (eigenwoningforfait) falls each year along with the remaining mortgage debt", "The notional rental value depends on the WOZ value (municipal property valuation), not on the debt."]], "1h.2"],
["A client compares an annuity mortgage and a linear mortgage of the same amount, with the same term and interest rate. What is correct?", [["With the linear mortgage he pays less interest in total, but the initial costs are higher", "With a linear mortgage the debt falls faster at the start, so less interest is paid; this is offset by higher starting costs."], ["With the linear mortgage he pays more interest over the whole term, but the initial costs are lower", "It is the other way round: linear starts higher and costs less interest in total."], ["Both forms cost the same amount of interest over the whole term", "Because the debt falls faster with a linear mortgage, the total interest is lower."], ["Only the annuity form meets the tax repayment requirement of at least annuity repayment within 30 years", "Linear repayment is faster than annuity repayment and therefore also meets the repayment requirement."]], "1i.3"],
["A client takes out a linear mortgage of €240,000 with a term of 30 years and an interest rate of 4.8%. What is the gross monthly payment in the first month?", [["€1,626.67", "The repayment is €240,000 / 360 = €666.67 and the interest is €240,000 × 4.8% / 12 = €960.00; together €1,626.67."], ["€1,259.20", "This is approximately the gross annuity for the same loan, not the linear starting payment."], ["€960.00", "This is only the interest portion; with a linear mortgage the fixed repayment is added to it."], ["€666.67", "This is only the fixed repayment portion; the interest must be added to it."]], "1i.3"],
["A client has an interest-only loan part of €180,000 at an interest rate of 3.9%. What is the gross monthly payment on this loan part?", [["€585.00", "€180,000 × 3.9% = €7,020 per year; divided by 12 that is €585.00 per month."], ["€702.00", "This is the annual amount divided by 10 instead of by 12."], ["€1,085.00", "With interest-only there is no repayment; so no repayment amount is added to the interest."], ["€7,020.00", "This is the interest per year, not per month."]], "1i.3"],
["What characterises a bank savings mortgage (bankspaarhypotheek)?", [["Savings are built up in a blocked account that repays the loan at the end", "The loan itself is interest-only; the deposits in the blocked owner-occupied home savings account are used for repayment at the end."], ["The loan is repaid linearly each month through an ordinary, freely accessible bank account at the same bank", "With a bank savings mortgage the loan is not repaid in the interim; saving takes place separately."], ["The deposits are invested in funds chosen by the client", "That is an investment mortgage; with a bank savings mortgage, savings earn interest."], ["The client pays only interest and builds up no savings balance", "That is an interest-only mortgage without a savings component."]], "1e.2"],
["For an owner-occupied home endowment policy (kapitaalverzekering eigen woning) or owner-occupied home savings account (spaarrekening eigen woning) under the transitional rules, a bandwidth applies to the deposits. What does it entail?", [["Highest annual deposit at most ten times the lowest", "The 1:10 bandwidth prevents the deposits from being heavily concentrated, as a condition for the exemption."], ["The deposit must be exactly the same every year", "Variation is permitted, as long as the 1:10 ratio is not exceeded."], ["The deposits may last for a maximum of ten years", "The bandwidth concerns the size of the deposits, not the duration."], ["The payout may be at most ten times the annual premium", "The bandwidth concerns the ratio between the premiums themselves, not the payout."]], "1e.12"],
["What is the purpose of a bridging loan when buying a new home?", [["To temporarily make the equity of the old, not yet sold home available for the new one", "The bridging loan finances the period between the purchase of the new home and the sale of the old one."], ["To permanently co-finance the purchase costs of the new home above the market value of the new home", "A bridging loan is temporary and intended for the equity, not to permanently finance purchase costs."], ["To extend the fixed-rate period of the old mortgage until the sale", "A bridging loan changes nothing about the fixed-rate period of the existing loan."], ["To permanently finance any residual debt on the old home", "A residual debt is not equity; a bridging loan in fact assumes equity."]], "1e.3"],
["Which risk is characteristic of an investment mortgage?", [["The invested capital may be insufficient at the end to repay the loan", "If returns disappoint, a shortfall arises, so that part of the debt remains outstanding at the end."], ["The mortgage interest rate rises automatically with the prices of the funds in which the client invests", "The mortgage interest rate is independent of investment results."], ["The loan becomes immediately repayable when prices fall", "A fall in prices does not automatically make the mortgage repayable."], ["The client pays transfer tax twice over the term, on purchase and on repayment", "Transfer tax has nothing to do with the type of mortgage."]], "1e.2"],
["Thijs (27) is a software developer and earns €55,000 gross per year. In 2026 he buys his first home, an apartment in Eindhoven. To keep his monthly payments low he wants to take out the entire mortgage as interest-only. He thinks he can simply deduct the interest, as his parents did for years. What is the tax consequence of his choice?", [["No owner-occupied home debt: interest not deductible, debt falls in box 3", "Since 2013, interest deduction requires that a new loan be repaid at least on an annuity basis within 30 years; an interest-only loan falls in box 3."], ["The interest is deductible, but at a lower rate than with an annuity mortgage", "There is no separate, lower deduction rate for interest-only loans; the interest is not deductible at all."], ["The interest is deductible for the first ten years and not thereafter", "A transitional period of ten years does not exist; without the repayment requirement there is no deduction from the start."], ["The interest is deductible as long as he voluntarily repays a little extra every year", "Voluntary extra repayments are not enough; under the agreement the loan must be repaid at least on an annuity basis within 30 years."]], "1a.1"],
["What does the transitional rule for existing owner-occupied home debts as at 31 December 2012 entail?", [["They keep the interest deduction without having to meet the repayment requirement", "Anyone who already had an owner-occupied home debt on 31 December 2012 is, for that amount, not subject to the obligation to repay on an annuity basis."], ["Those debts must still be fully repaid before 2030 to retain the interest deduction", "The transitional rule contains no mandatory repayment before a certain year."], ["Those debts are deductible without time limit from 2013", "Even under the transitional rule the maximum deduction period of 30 years continues to apply."], ["Those debts may be increased without limit while retaining the transitional rule", "An increase after 2012 falls under the new rules and must meet the repayment requirement."]], "1a.1"],
["Henk (61) and Marja (59) have lived in a detached house in Ede since 2009, financed with an interest-only mortgage of €200,000. Henk still works as an account manager, Marja is a part-time administrative employee. In 2026 they want to renovate the bathroom and kitchen and borrow an extra €40,000 for it. They hope the new part can also be interest-only, like the rest. What applies to the new loan part if they want to deduct the interest?", [["The new part must be repaid at least on an annuity basis within 30 years; the old part may remain interest-only", "The transitional rule protects only the existing debt from before 2013; the repayment requirement applies to new owner-occupied home debt."], ["The new part may also remain interest-only, because the old part from before 2013 falls under the transitional rule", "The transitional rule does not apply to an increase; it must meet the repayment requirement."], ["The entire loan of €240,000 must now be repaid on an annuity basis over the remaining term", "The old part keeps its transitional rule; only the new part must be repaid."], ["Interest on a loan for a renovation is never deductible, only interest for the purchase", "A loan for improvement or maintenance of the owner-occupied home can be owner-occupied home debt."]], "1a.1"],
["Karin (44) and Joost (46) are selling their terraced house in Amersfoort for €420,000; the selling costs are €12,000. Their owner-occupied home debt is €260,000. They are buying a detached house for €525,000 with €23,000 in purchase costs. They want to borrow as much as possible and put their equity in a savings account. What is their maximum new owner-occupied home debt?", [["€400,000", "The owner-occupied home reserve is €420,000 − €12,000 − €260,000 = €148,000; the acquisition costs are €548,000; €548,000 − €148,000 = €400,000."], ["€388,000", "Here the selling costs have been forgotten, so the owner-occupied home reserve has been calculated too high (€160,000)."], ["€377,000", "Here the purchase costs have not been included in the acquisition costs of the new home."], ["€548,000", "Here the owner-occupied home reserve has been ignored; under the top-up rule (bijleenregeling) the equity must be put in, otherwise that part falls in box 3."]], "1h.4"],
["Ruud (38) sold his apartment in The Hague at the beginning of 2022 with equity of €60,000. He moved abroad for work and rented there. At the end of 2026 he returns and buys a home in Leiden. He wonders whether he still has to put in the old equity. What is correct for tax purposes?", [["The reserve has lapsed after three years; he no longer has to put in the old equity", "An owner-occupied home reserve applies for three years after the disposal; after that it lapses."], ["He must still put in the equity in full, because the reserve never lapses", "The reserve does lapse: after three years the equity no longer has to be put in."], ["He is not entitled to interest deduction for the new home, because he lived abroad for a number of years", "Living abroad does not exclude interest deduction for a new owner-occupied home in the Netherlands."], ["After three years the equity is nevertheless taxed in box 1 of his return", "The lapsing of the reserve does not lead to taxation in box 1; the reserve simply disappears."]], "1a.1"],
["Which costs are directly deductible as financing costs in box 1 when buying an owner-occupied home?", [["The advice and intermediation costs for the mortgage", "Costs connected with taking out the loan, such as advice, valuation for the loan and the mortgage deed, are deductible."], ["The transfer tax", "Transfer tax is an acquisition cost of the home, not a financing cost, and is therefore not deductible."], ["The notary costs of the deed of transfer at the conveyance", "The deed of transfer is part of the acquisition of the home; only the mortgage deed is deductible."], ["The costs of the buyer's estate agent and the structural survey", "Estate agent costs are acquisition costs and not deductible as financing costs."]], "1e.7"],
["How does the notional rental value (eigenwoningforfait) work in income tax?", [["As an addition to income in box 1, as a percentage of the WOZ value", "The notional rental value is the tax benefit of living in the owner-occupied home; deductible interest and costs are deducted from it."], ["As a deduction that reduces the taxable income from work and home in box 1", "The notional rental value in fact increases income; the interest is the deduction."], ["As a municipal tax levied annually", "Municipalities levy OZB (property tax); the notional rental value is part of income tax."], ["As a percentage of the mortgage debt, taxed in box 3", "The notional rental value depends on the WOZ value and falls in box 1, not in box 3."]], "1h.4"],
["A client has repaid his mortgage in full and still lives in the home. What applies to the deduction for no or a small owner-occupied home debt (Hillen Act)?", [["A deduction partly offsetting the notional rental value, being phased out", "Since 2019 the Hillen deduction has been phased out over thirty years, so that an increasing part of the notional rental value is taxed."], ["The notional rental value lapses because there is no longer a debt", "The notional rental value remains as long as the home is the main residence, even without a debt."], ["He may leave the entire notional rental value outside the tax charge forever", "That was the effect before 2019; the compensation is now being phased out."], ["He receives a refund of the interest he paid in the past", "The Hillen Act concerns the notional rental value, not a refund of interest paid."]], "1h.4"],
["Fatima (36) and Youssef (39) have bought a new home in Almere and have moved. Their old apartment in Amsterdam is empty and for sale, but a buyer has not yet been found. Both homes have a mortgage. They ask how long they may still deduct the interest on the old home. How long can the old home continue to count as an owner-occupied home for tax purposes?", [["In the year it became empty and the three years after, as long as it is for sale", "An empty home that is for sale remains an owner-occupied home during that period."], ["Until the end of the month in which they moved with their family to the new home in Almere", "The law in fact gives a longer period to sell the home."], ["A maximum of six months after the move, after which the home falls in box 3", "A period of six months does not exist; the period is the year it became empty plus three years."], ["Without limit, as long as the home demonstrably remains for sale", "The period is limited; after that the home falls in box 3 together with the debt."]], "1e.11"],
["Bram (30) and Eva (28) rent an apartment in Groningen. They are buying a new-build home in a project on the edge of the city, to be delivered in one and a half years. Until delivery they stay in their rented home and are already paying interest on their new mortgage. They want to know whether that interest is deductible. What applies?", [["It may already be an owner-occupied home if they expect to occupy it within three years", "A home under construction that is to be occupied as the main residence within three years can already count as an owner-occupied home."], ["The interest is deductible only from the day they are registered at the new address", "Registration is not decisive; the law has a rule for homes under construction."], ["Construction-period interest is never deductible; only mortgage interest after delivery counts", "Interest during the construction period can also be deductible if the conditions are met."], ["Until delivery the loan falls in box 3, because the home does not yet exist", "Thanks to the rule for homes under construction, the loan does not have to fall in box 3."]], "1a.1"],
["What applies to the interest on a residual debt after the sale of an owner-occupied home?", [["Only if it arose between 29-10-2012 and 31-12-2017: deduction for a maximum of 15 years", "This temporary rule has ended; for residual debts arising later the interest is no longer deductible."], ["Interest on any residual debt is always deductible for 30 years", "A residual debt is not an owner-occupied home debt; only the temporary rule gave limited deduction."], ["Interest on a residual debt is deductible if the client buys a home again", "A new purchase does not turn a residual debt into owner-occupied home debt."], ["Interest on a residual debt is deductible only with an NHG (National Mortgage Guarantee) mortgage", "NHG can forgive a residual debt, but does not regulate interest deduction."]], "1e.9"],
["Mark (42) is an installation fitter and lives with his family in a semi-detached house in Apeldoorn. His mortgage is €210,000, while the home is now worth €420,000. He wants to increase the mortgage by €25,000 to buy an electric car, because the mortgage interest rate is lower than the interest rate on a car loan. He assumes he can deduct that interest. How is the new loan part treated for tax purposes?", [["It falls in box 3, because the money is not spent on the owner-occupied home", "Only loans for the purchase, improvement or maintenance of the owner-occupied home are owner-occupied home debt."], ["It is deductible, because a mortgage right has been established on the home", "The mortgage right is security and does not determine the tax treatment; the use of the money is decisive."], ["It is deductible, provided he repays it on an annuity basis within thirty years", "The repayment requirement is an additional condition, but the money must also be spent on the home."], ["It falls in box 2, because a car is an asset", "Box 2 concerns a substantial interest in a company, not private debts."]], "1a.1"],
["Peter (58) and Annemiek (57) live in a detached house in Hilversum. Now that the children have left home, they are buying a holiday home in Zeeland, where they stay about ten weekends a year. They finance that home with a separate mortgage at their own bank. They hope to be able to deduct that interest too. What is correct?", [["The holiday home and the loan fall in box 3; the interest is not deductible in box 1", "Only the main residence is an owner-occupied home; a second home falls in box 3 together with the debt."], ["Both homes count as owner-occupied homes, because they both stay in them regularly and for longer periods", "There can be only one owner-occupied home: the main residence."], ["The interest on the holiday home is deductible, but at a lower rate", "For a second home there is no interest deduction in box 1, not even at a lower rate."], ["For the holiday home they pay notional rental value instead of box 3 tax", "The notional rental value applies only to the owner-occupied home (the main residence)."]], "1h.4"],
["Daan (26) has just started as a lawyer and is buying an apartment in Nijmegen. His parents lend him €50,000 from their savings, so that he has to borrow less from the bank. They agree an arm's-length interest rate and record the loan in writing. Daan wants to deduct the interest he pays to his parents. What is required for this, among other things?", [["That the loan is repaid at least on an annuity basis within 30 years and that he states the loan details in his return", "The repayment requirement and the duty to provide information also apply to a family loan; otherwise the debt falls in box 3."], ["That the loan is recorded by a notary and is also placed under the NHG (National Mortgage Guarantee) guarantee of Stichting WEW", "A notarial deed or NHG is not a condition for interest deduction on a family loan."], ["That his parents, as lender, hold an AFM licence", "Private individuals who make a one-off loan to their child do not need a licence."], ["That the loan is interest-only, so that no gift arises", "An interest-only loan in fact does not meet the repayment requirement."]], "1e.3"],
["Two fiscal partners jointly own their owner-occupied home. How may they divide the balance of the notional rental value and deductible costs?", [["In any proportion they wish between the two partners", "Fiscal partners may divide joint components, such as the owner-occupied home balance, in any proportion they wish."], ["Always compulsorily in equal halves, regardless of who pays the interest", "Division in equal halves is not compulsory for fiscal partners."], ["Entirely to the partner with the lowest income", "There is no obligation to allocate the balance to the partner with the lowest income."], ["In proportion to the ownership shares in the deed of transfer", "For fiscal partners the ownership proportion is not decisive for the division."]], "1h.4"],
["A client refinances an annuity owner-occupied home debt taken out in 2016 to another lender. What applies for tax purposes to the new loan?", [["The repayment schedule and the remaining term of the old loan continue", "When refinancing, the original repayment schedule continues; the client does not get a new period of 30 years."], ["A new term of 30 years starts for interest deduction", "Refinancing does not give a new deduction period; the term already elapsed counts."], ["The new loan may be interest-only if the interest rate is lower", "A lower interest rate changes nothing about the repayment requirement."], ["The new loan automatically falls under the transitional rule for debts from before 2013", "A loan from 2016 never had a transitional rule."]], "1a.1"],
["Chantal (42) and Erwin (45) are buying a detached house in Doetinchem for €450,000, of which approximately €150,000 is land value. Their lender requires a buildings insurance policy. Erwin wants to insure the home for the purchase price, so that everything is covered. The adviser explains how the insured amount should be determined. On which value should the sum insured of the buildings insurance be based?", [["On the rebuilding value: what it costs to rebuild the home after total loss", "The land is not lost in a fire; the insurance covers rebuilding the structure, so the rebuilding value is the measure."], ["On the purchase price of €450,000, including the land under the home", "The land does not need to be insured; insuring for the purchase price usually leads to over-insurance."], ["On the WOZ value that the municipality sets annually for the home", "The WOZ value is a value including land for tax purposes, not a rebuilding value."], ["On the amount of the mortgage, so that the lender is fully covered in the event of damage to the home", "The debt says nothing about the cost of rebuilding; the insurance must match the home itself."]], "3c.6"],
["Why does a client with NHG (National Mortgage Guarantee) usually get a lower interest rate?", [["Because the guarantee reduces the lender's risk", "The guarantee limits the lender's loss in the event of a forced sale; that lower risk is passed on in the interest rate."], ["Because the government pays part of the interest directly", "There is no interest subsidy; the benefit comes from the lower risk."], ["Because NHG mortgages do not fall under the TRHK", "NHG mortgages fall under the TRHK as normal, with additional NHG standards."], ["Because no mortgage right is established with NHG", "A mortgage right is also established with NHG; NHG comes on top of it."]], "1b.3"],
["Jeroen (41) and Sabine (40) bought a home in Breda with NHG (National Mortgage Guarantee) in 2019. After their divorce neither of them can afford the home alone, so it is sold. The proceeds are lower than the mortgage, leaving a residual debt. They informed the lender in good time and are selling in consultation at a fair price. When can Stichting WEW forgive the residual debt?", [["In the case of a recognised cause such as a divorce, provided they acted responsibly", "Forgiveness is possible for causes such as the end of a relationship, unemployment, incapacity for work or death, provided the client has behaved responsibly."], ["Always, regardless of the cause of the sale and the behaviour of the clients", "Forgiveness is not automatic; the cause and the client's behaviour are assessed."], ["Only if one of them has reached the AOW (state pension) age and has no pension capital", "Age is not a condition for forgiveness."], ["Never, because NHG protects only the lender and not the consumer", "NHG also protects the consumer, who under conditions does not have to pay a residual debt."]], "1e.9"],
["How does the NHG (National Mortgage Guarantee) guarantee develop over the term?", [["It falls every month as if the loan were repaid on an annuity basis in 30 years", "The cover decreases according to an annuity schedule, even if the loan is actually repaid differently."], ["The guarantee stays equal to the original loan amount with NHG for the whole term", "The guarantee in fact falls over time."], ["The guarantee rises along with the value of the home", "The guarantee follows a fixed phase-down schedule, not the value of the home."], ["The guarantee lapses automatically after ten years", "The guarantee in principle runs for the whole term, but it does fall."]], "1b.3"],
["How is the one-off guarantee fee for NHG (National Mortgage Guarantee) treated for tax purposes?", [["As deductible financing costs of the owner-occupied home debt", "The NHG fee is a cost of obtaining the loan and is therefore deductible in box 1."], ["As an acquisition cost of the home that is not deductible in box 1", "The fee belongs to the financing, not to the acquisition of the home."], ["As a premium that is exempt in box 3", "Box 3 plays no role here; this concerns deductible costs in box 1."], ["As a donation to Stichting WEW, deductible as a gift", "The fee is a payment for the guarantee, not a donation."]], "1e.7"],
["What is meant by market value in a valuation report for mortgage financing?", [["The estimated price in a sale between a willing buyer and seller", "Market value assumes an arm's-length transaction after proper marketing, with the parties acting without compulsion."], ["The minimum amount the home would fetch at a forced auction", "That is the enforcement or auction value, which is usually lower."], ["The WOZ value (municipal property valuation) set by the municipality", "The WOZ value is a tax value with a different reference date and purpose."], ["The purchase price from the purchase agreement", "The purchase price may differ from the market value; the valuer sets the value independently."]], "1b.3"],
["What is the role of a validation institute in relation to a valuation report?", [["It checks that the report was drawn up according to the standards", "Validation tests the quality and substantiation of the report, so that the lender can rely on it."], ["It sets the final value of the home itself", "The valuer sets the value; the institute checks the report."], ["It determines the level of the mortgage interest rate", "The interest rate is set by the lender, not by a validation institute."], ["It carries out a structural survey of the home and reports the defects", "Validation is a check on the valuation report, not a structural investigation."]], "1b.3"],
["Noor (34) and Jesse (35) are buying a 1930s house in Haarlem for €300,000. They want to renovate straight away for €40,000: a new kitchen, a dormer window and a second bathroom. The valuer sets the market value after renovation at €350,000. They ask which value the bank uses for their maximum mortgage. On which value is the LTV test based?", [["On the market value after renovation of €350,000, as set by the valuer", "When financing a renovation, the valued market value after renovation may be used as the value of the home."], ["On the purchase price of €300,000, because the renovation still has to take place at the time of purchase", "The purchase price without renovation does not do justice to the value created by the renovation."], ["On the purchase price plus the renovation costs, together €340,000", "The LTV is based on the valued market value, not on the sum of costs."], ["On the WOZ value (municipal property valuation) of the home from before the renovation", "The WOZ value is not the measure for the LTV in this financing."]], "1a.2"],
["Why must a valuer be independent of the transaction he is valuing?", [["To prevent interests in the sale or financing from influencing the valuation", "The lender bases the loan on the value; it must be determined objectively."], ["Because otherwise the valuer may not calculate transfer tax on the purchase price of the home", "Valuers do not calculate transfer tax; the notary does that in the return."], ["Because the valuer has to sign the purchase agreement", "The valuer is not a party to the purchase agreement."], ["Because only an independent valuer may register the energy label of the home", "An energy label is registered by a recognised energy adviser, separately from the valuation."]], "1b.3"],
["A client thinks that a valuation report also gives certainty about hidden defects in the home. What is correct?", [["A valuation is no structural survey; the structure needs separate investigation", "The valuer assesses the value and the visible condition in broad terms, but does not carry out in-depth structural investigation."], ["A validated valuation report guarantees that there are no defects", "Validation concerns the quality of the report, not the absence of defects."], ["The valuer is liable for all defects discovered later", "The valuer is not responsible for defects that are not reasonably visible during a valuation."], ["The lender reimburses the repair costs if the valuer missed defects during the valuation", "The lender gives no guarantee on the structural condition of the home."]], "1b.3"],
["How does a mortgage right on a home come into being?", [["Through a notarial deed that is registered in the public registers (Land Registry)", "Establishing a mortgage on registered property requires a notarial deed and registration in the public registers."], ["Through the client and any partner signing the lender's binding offer", "The offer leads to a credit agreement, but does not yet establish a mortgage right."], ["Through registration of the loan with the BKR (Dutch credit registration bureau)", "The BKR registers credit, but does not establish a real right."], ["Through a private deed between client and lender, authenticated by the Land Registry", "A private deed is insufficient, even with authentication; a notarial deed is mandatory."]], "1f.3"],
["What does the mortgagee's right of summary enforcement (parate executie) entail?", [["On default, he may have the collateral sold himself without a prior court judgment", "Summary enforcement gives the mortgagee the right to sell the home by public auction before the notary."], ["He may occupy or let the home himself until the entire arrears have been made up", "The mortgage right gives no right to occupy the home oneself."], ["He may unilaterally raise the interest rate in the event of payment arrears", "Summary enforcement concerns the sale of the collateral, not interest rate changes."], ["He must always first ask the AFM for permission before having the collateral publicly auctioned", "The AFM plays no role in the enforcement of collateral."]], "1f.3"],
["A mortgagee does not want to auction a home under enforcement but sell it by private treaty. What is needed for that?", [["Permission from the interim relief judge for the private sale", "Private enforcement sale is possible if the interim relief judge approves the purchase agreement."], ["Only a new valuation by a recognised valuer", "A valuation is useful, but does not replace the court's permission."], ["Permission from Stichting WEW, even if the loan was granted without NHG (National Mortgage Guarantee)", "Without NHG, Stichting WEW has no role, and the court's permission remains necessary."], ["A resolution of the general meeting of the Owners' Association (VvE) of the apartment complex", "The VvE does not decide on the enforcement of an apartment right."]], "1f.3"],
["Two mortgage rights of different lenders rest on a home. What in principle determines which mortgage has priority on enforcement?", [["The time of registration in the public registers", "The ranking of mortgages in principle follows the order of registration; the first registration has priority."], ["The size of the amount borrowed under each mortgage right", "A larger loan does not give a higher ranking."], ["The level of the interest rate and the term of each loan", "The level of the interest rate plays no role in the ranking."], ["The date of the purchase agreement at the notary", "The purchase agreement does not determine the ranking of mortgages."]], "1f.3"],
["What is characteristic of a bank mortgage (bankhypotheek)?", [["It also covers future debts, up to the registered amount", "As a result, further borrowing is possible within the registration without a new mortgage deed."], ["It covers only the original loan", "That describes a fixed (ordinary) mortgage, not a bank mortgage."], ["It can be established only by a bank, not by an insurer", "The term concerns the scope of the security, not the type of lender."], ["It lapses at the end of the fixed-rate period", "A mortgage right does not lapse at the end of a fixed-rate period."]], "1e.4"],
["Wim (52) bought his home in Deventer long before his marriage and is the sole owner in the Land Registry. He is married to Ingrid, who has lived in the home with him since they married. Wim wants to take an additional mortgage on the home to buy a camper van. He thinks Ingrid has nothing to do with it, because it is his house. What is correct?", [["He needs Ingrid's consent, because she lives in the home he wants to mortgage", "To encumber a home occupied by spouses, the consent of the other spouse is required, even if that spouse is not the owner."], ["He does not need consent, because he is the sole owner of the home", "The law protects the spouse living in the home, regardless of who is the owner."], ["He needs the consent of the subdistrict court judge for every mortgage on the home", "The court only comes into play if the spouse refuses consent without good reason."], ["Ingrid's consent is needed for the mortgage only if they married with a prenuptial agreement", "The consent requirement applies regardless of the matrimonial property regime."]], "1a.4"],
["What is leasehold (erfpacht) under Book 5 of the Dutch Civil Code (BW)?", [["A real right to use another's property, for ground rent (canon)", "The leaseholder has an independent real right to the owner's land and usually pays ground rent for it."], ["A lease of land that can be terminated annually", "Leasehold is a real right and not a lease, and cannot simply be terminated annually."], ["A mortgage right in favour of the municipality", "Leasehold is a right of use, not a right of security."], ["The right to have one's own buildings in, on or above another person's land", "That is the right of superficies (opstalrecht), another real right under Book 5 of the Dutch Civil Code (BW)."]], "1a.4"],
["What is an important disadvantage of a variable mortgage interest rate for the consumer?", [["The monthly payments can rise immediately if interest rates go up", "With a variable interest rate the consumer bears the interest rate risk; if the market rate rises, the costs rise."], ["Extra repayment is never permitted with a variable interest rate", "With a variable interest rate in particular, penalty-free repayment is usually widely possible."], ["With a variable rate the interest rate is always higher than with a long fixed-rate period", "That depends on the interest rate structure; variable is often in fact lower."], ["A variable interest rate is not tax-deductible", "Deductibility does not depend on the form of interest rate."]], "1e.2"],
["What is a capped rate (plafondrente)?", [["A variable interest rate that cannot rise above an agreed maximum", "The client benefits from falls in interest rates, while the cap limits the risk of a rise."], ["A fixed interest rate that automatically falls to the market level after ten years", "A capped rate is variable with a maximum, not a fixed rate with a fall."], ["The maximum interest rate that the AFM sets annually for all mortgages", "The AFM does not set a maximum interest rate for mortgages; the cap is a product arrangement."], ["An interest rate equal to the statutory interest rate", "The statutory interest rate applies in the event of payment arrears and is unrelated to the capped rate."]], "1e.2"],
["Between issuing the offer and executing the deed, the mortgage interest rate falls. Which product condition ensures that the client benefits from that fall?", [["An interest rate reduction guarantee (rentedaalgarantie or rentepluk)", "With it, at execution the client gets the lowest interest rate from the period between offer and execution."], ["Interest averaging when refinancing", "Interest averaging concerns incorporating a penalty on interim refinancing into a new interest rate."], ["A capped rate on the loan", "A cap limits a variable interest rate upwards, but gives no right to a lower offer rate."], ["An extended fixed-rate period", "A longer fixed-rate period changes nothing about interest rate falls during the offer period."]], "1h.6"],
["Many lenders work with risk surcharges per LTV bracket. What can a client do if his home rises considerably in value?", [["Have a new valuation done for a possibly lower risk surcharge", "A lower LTV means less risk for the lender; depending on the terms, the surcharge may fall."], ["Apply to the Dutch Tax and Customs Administration for a higher interest deduction", "The value of the home has no effect on the amount of deductible interest."], ["Have his fixed-rate period extended free of charge to thirty years at the same interest rate", "An increase in value gives no right to a free extension of the fixed-rate period at the same interest rate."], ["Have the NHG (National Mortgage Guarantee) guarantee increased to the new value", "The NHG guarantee follows a fixed phase-down schedule and is not increased when the value rises."]], "1h.6"],
["A client with a tight budget wants certainty about his monthly payments. Why does a long fixed-rate period often suit him?", [["Because his costs are fixed for a long time and he is less vulnerable to rate rises", "A long fixed-rate period limits the interest rate risk, which is important if an increase in costs cannot be absorbed."], ["Because the interest rate with a long fixed-rate period is always the lowest of all terms", "A longer fixed-rate period often has a higher interest rate; the advantage is certainty."], ["Because he then never has to pay a charge for early repayment, not even when moving house", "Even with a long fixed-rate period, a charge may be due on extra repayment above the penalty-free allowance."], ["Because he then does not have to undergo a creditworthiness test", "The test always applies; only the test rate may differ."]], "1d.2"],
["Under the Wft, what is the maximum charge a lender may ask on early repayment of a mortgage?", [["No more than the financial loss the lender suffers as a result of the early repayment", "The charge is compensation for loss of interest and may not exceed the actual loss."], ["A fixed percentage of the original principal, regardless of the market interest rate and the remaining fixed-rate period", "A fixed percentage unrelated to the actual loss is not permitted."], ["The full interest over the remaining term of the loan", "That would be much higher than the actual loss."], ["The amount the client saves by refinancing", "The client's saving is not the measure; what counts is the lender's loss."]], "1e.10"],
["Lotte (45) has received an inheritance and wants to repay her mortgage of €150,000 in one go. Her interest rate of 2.5% is still fixed for six years. The interest rate her lender now charges for a comparable fixed-rate period is 3.8%. She is afraid of a high penalty. What is correct in principle?", [["No charge, because with a higher market interest rate the lender suffers no loss of interest", "The charge may not be higher than the financial loss; if the lender can lend the money out at a higher rate, there is no loss."], ["She pays a charge, because she repays in full within the fixed-rate period", "Repaying within the fixed-rate period leads to a charge only if the lender suffers a loss of interest."], ["The lender must pay her a compensation for the interest rate difference", "A payment by the lender to the client is in this case neither usual nor mandatory."], ["Repaying in full is not permitted as long as the current market interest rate is higher than her contract rate", "Early repayment is always permitted; the only question is whether a charge is due."]], "1e.10"],
["On which factors does the level of the charge for early repayment mainly depend?", [["The interest rate difference, the remaining fixed-rate period and the amount above the penalty-free allowance", "The larger the interest rate difference, the longer the remaining period and the higher the amount subject to a charge, the higher the charge."], ["The WOZ value (municipal property valuation) of the home, the energy label and the client's age at refinancing", "These factors do not determine the charge."], ["The client's income, the value of the home and the number of monthly instalments already paid", "Income plays no role, and what counts is the remaining fixed-rate period rather than the instalments paid."], ["The amount of the original advice costs and notary costs", "The costs of taking out the loan at the time do not determine the charge."]], "1e.10"],
["Gerard (50) and Ria (49) have a mortgage of €230,000 with a bank in their home town of Tilburg. Their ten-year fixed-rate period ends in two months. Another lender offers them a lower interest rate. They want to refinance in full on the interest reset date. What applies to a charge for early repayment?", [["On the interest reset date no charge is due, because the fixed-rate period then ends", "On the interest reset date the lender suffers no loss of interest, so repayment is penalty-free."], ["They pay a charge on the next fixed-rate period that their current bank has offered them", "A new fixed-rate period has not yet been agreed, so there is no loss of interest."], ["They always pay a fixed charge of one month's interest on the principal", "A fixed charge of one month's interest is not a rule; the charge must match the actual loss."], ["Penalty-free refinancing is only possible once the full term of 30 years has elapsed", "The interest reset date is in fact the moment at which penalty-free repayment is possible."]], "1e.10"],
["A client refinances his owner-occupied home debt to a lower interest rate and pays a charge for early repayment in doing so. How is that charge treated for tax purposes?", [["As deductible costs of the owner-occupied home debt", "A penalty on refinancing an owner-occupied home debt is deductible as financing costs."], ["As a non-deductible acquisition cost of the home", "The charge relates to the financing, not to the acquisition of the home."], ["As a debt in box 3", "The charge is a cost, not a debt; it is deductible in box 1."], ["As income that is tax-free for the lender", "What the lender does with the charge does not determine the client's tax position."]], "1e.7"],
["What is the ESIS for mortgage credit?", [["A European Standardised Information Sheet on the credit offered", "The ESIS stems from the Mortgage Credit Directive and makes offers comparable through a fixed structure."], ["A European register of mortgages with payment arrears among consumers", "The ESIS is not a register; arrears are registered in the Netherlands with the BKR (Dutch credit registration bureau)."], ["A tax form for the return of mortgage interest", "The ESIS is pre-contractual information, not a tax form."], ["A certificate with which the adviser demonstrates his professional competence", "Professional competence is shown by Wft diplomas and PE (permanent education), not by the ESIS."]], "1a.6"],
["When must the consumer receive the ESIS at the latest?", [["In good time before he is bound by a credit agreement or offer", "The consumer must be able to compare and consider the information before committing."], ["Only after the mortgage deed has been executed", "After execution it is too late to use the information in making the choice."], ["Within a year after taking out the mortgage, with the lender's first annual statement", "The ESIS is pre-contractual and must be provided before commitment."], ["Only if the consumer expressly asks for it", "Providing it is an obligation for the provider, not dependent on a request."]], "1a.6"],
["What does the annual percentage rate of charge (APRC; jaarlijks kostenpercentage, JKP) stated in the ESIS express?", [["The total costs of the credit as a percentage per year", "The APRC includes interest and ancillary costs, so that offers are better comparable."], ["Only the nominal debit interest rate on an annual basis", "The APRC includes more than the interest, such as mandatory ancillary costs."], ["The percentage of income spent on housing costs", "That is the financing burden, not an APRC."], ["The part of the value of the home that is financed", "That is the LTV, not a cost percentage."]], "1e.1"],
["Which information must be included in the ESIS, among other things?", [["The conditions and possible costs of early repayment", "The ESIS contains a fixed section on the right to early repayment and the charge that may apply to it."], ["The adviser's advice on the best-fitting insurance", "The ESIS describes the credit; the advice is recorded separately."], ["The WOZ notice (municipal property valuation notice) from the municipality", "The WOZ notice is not part of the ESIS."], ["The outcome of the BKR (Dutch credit registration bureau) check of the partner", "Personal test results are not a standard part of the ESIS."]], "1a.6"],
["Sophie (27) has worked for nine months as a laboratory technician at a hospital in Leiden, on a one-year contract. She earns €40,000 gross per year including holiday allowance. She wants to buy a home together with her boyfriend. Her manager is satisfied and expects to convert her contract into a permanent contract. Which statement from the employer usually makes it possible for lenders to include her income in full?", [["An employer's statement in which the employer declares the intention to give her a permanent contract", "With a statement of intent for permanent employment, lenders usually treat a temporary income as permanent income."], ["A statement that she performs well and has successfully completed her probationary period at the hospital", "Performing well says nothing about the continuation of employment after the contract ends."], ["A recent payslip showing that she has already been employed for nine months", "A payslip shows income, not whether the contract will be continued."], ["A statement from her trade union about the wages in the collective labour agreement for hospitals", "A collective agreement overview says nothing about her personal employment."]], "2c.2"],
["What is a prospects statement (perspectiefverklaring)?", [["A statement on the labour market prospects of a flexible worker", "A prospects statement can make it possible to obtain a mortgage if there is no statement of intent from the employer."], ["A statement by the lender about the expected development of interest rates", "The prospects statement concerns the client's income, not interest rates."], ["A statement by the valuer about the expected increase in value", "Value expectations are no basis for this statement, nor for the creditworthiness test."], ["A statement from the UWV (Employee Insurance Agency) about an existing WW (unemployment benefit)", "A WW benefit is not a labour market prospect and the UWV does not issue this statement."]], "2c.2"],
["What is Income Determination for Employees (Inkomensbepaling Loondienst, IBL)?", [["A method to determine the test income using UWV data", "IBL uses the insurance statement of the UWV (Employee Insurance Agency) to establish income over the past period."], ["A tax scheme to offset mortgage interest through payroll tax", "That is the provisional assessment or refund, not an income determination for the mortgage."], ["A mandatory insurance against loss of income on unemployment", "IBL is not insurance, but a calculation method for income."], ["An income statement for self-employed entrepreneurs", "IBL is intended for employees; other methods apply to entrepreneurs."]], "1i.4"],
["A self-employed entrepreneur applies for a mortgage. How is his income usually established?", [["Based on figures over several years or an income statement", "For entrepreneurs, results over several years are examined, because income can fluctuate."], ["Only on the basis of the turnover of the last month", "One month's turnover says little about sustainable income."], ["On the basis of an employer's statement that he signs himself", "An entrepreneur cannot issue an employer's statement about himself as proof of income."], ["On the basis of the expected income from his business plan", "Expectations without a track record are usually insufficient to grant credit responsibly."]], "2c.2"],
["After his divorce, Erik (47) is looking for an apartment of his own in Utrecht. He earns €70,000 gross per year as a project manager. He pays partner alimony to his ex-wife and child support for his two children every month. He wonders how much he can still borrow. How does the partner alimony count in determining his maximum mortgage?", [["Partner alimony paid reduces his test income, because it is a fixed obligation", "The TRHK deducts partner alimony paid from the test income."], ["The partner alimony increases his test income, because he may deduct it for tax purposes", "Deductibility does not turn the alimony into additional income; it remains a cost."], ["The partner alimony plays no role, because only his gross salary counts for the lending standards", "Alimony weighs on the ability to pay and is therefore taken into account."], ["The partner alimony reduces the value of the home used for the LTV", "Alimony has no relation to the value of the home."]], "1i.4"],
["A client buys an apartment in a building with an Owners' Association (VvE). How is the insurance of the building and the household contents usually arranged?", [["The VvE insures the building; the owner insures his own household contents", "The building is insured collectively by the VvE; the resident arranges the household contents and any improvements of his own."], ["Each owner takes out his own buildings insurance for his part of the building", "With apartment rights the VvE arranges the buildings insurance for the whole building."], ["The VvE insures both the building and the household contents of all residents", "Household contents fall outside the VvE policy; each resident must insure them himself."], ["He does not need to insure an apartment himself, because the lender bears the risk of damage", "The lender in fact requires the collateral to be properly insured; this is arranged through the VvE."]], "1e.5"],
["A BKR (Dutch credit registration bureau) check shows that a client has a revolving credit. What does the lender do with that?", [["It takes the cost of the credit into account as a financial obligation", "Existing credit weighs on the ability to pay and therefore reduces the maximum mortgage."], ["It ignores the credit as long as no arrears have been registered with the BKR", "Even without arrears the credit is an obligation that counts."], ["It increases the test income by the credit limit", "A credit limit is not income."], ["It must always reject the application", "An existing credit is not an automatic ground for rejection."]], "1e.6"],
["Which income component of an employee counts in principle in the gross test income?", [["The holiday allowance he receives annually", "The test income is the gross annual income including fixed components such as holiday allowance."], ["A one-off bonus without a structural character", "Incidental payments are not sustainable and in principle do not count."], ["The expected pay rise over three years", "Future increases are uncertain and do not count as income."], ["The refund of mortgage interest deduction", "The tax benefit is already included in the financing burden percentages and is not added to income."]], "2c.2"],
["A couple buys a home; only partner A has an income. What is the main purpose of term life insurance (overlijdensrisicoverzekering) in the advice?", [["Ensuring that the partner can bear the costs after A's death", "The cover is set so that after death the debt falls far enough for the costs to fit the survivor's income."], ["Ensuring that the mortgage interest remains deductible after death", "The interest deduction does not depend on term life insurance."], ["Raising the NHG (National Mortgage Guarantee) cost limit", "Insurance has no effect on the NHG cost limit."], ["Meeting the tax repayment requirement for the loan", "The repayment requirement relates to the loan, not to an insurance policy."]], "1i.6"],
["An employee becomes ill for a long period. How does his income develop, in broad terms?", [["Two years of continued pay, then possibly a lower WIA benefit", "After the continued-pay period (WIA: Work and Income according to Labour Capacity Act) the income may fall sharply; this must be worked through in the mortgage advice."], ["He keeps his full salary from the employer until retirement", "Continued payment of wages during illness is limited to two years."], ["He immediately receives a WW (unemployment benefit) from the UWV (Employee Insurance Agency)", "WW is for unemployment, not for illness during an existing employment."], ["NHG (National Mortgage Guarantee) takes over the monthly payments from the first day of illness", "NHG does not pay monthly costs; it can play a role only in a forced sale."]], "1a.4"],
["Kevin (34) has worked as a self-employed carpenter for five years and makes an average profit of €50,000 per year. With his partner Iris, who works part-time as an employee, he is buying a home in Amersfoort. He has no incapacity-for-work insurance and thinks the premium is too expensive. Iris asks what happens if he can no longer work because of an accident. What is a particular point of attention in the advice on incapacity for work?", [["As a self-employed person Kevin has no WIA cover and must make provision himself", "Self-employed people do not fall under the WIA; without their own insurance or a buffer, his income largely falls away in the event of incapacity for work."], ["Through his clients Kevin continues to receive his income for two years", "Continued payment of wages during illness applies to employees, not to the self-employed."], ["Through the NHG (National Mortgage Guarantee) guarantee on the mortgage, Kevin is automatically insured against incapacity for work", "NHG is not incapacity-for-work insurance and does not supplement income."], ["In the event of incapacity for work the lender forgives Kevin's mortgage", "The debt remains; forgiveness in the event of incapacity for work does not exist."]], "1i.6"],
["On what does the duration of a WW (unemployment benefit) depend, in broad terms?", [["On the employee's employment history", "The longer someone has worked, the longer the WW benefit can last, up to a statutory maximum."], ["On the size of the mortgage", "The mortgage has no effect on the WW duration."], ["On the age of the partner", "The WW is an individual employee insurance, independent of the partner."], ["On the fixed-rate period of the loan", "The fixed-rate period plays no role in the WW."]], "1a.4"],
["Marloes (38) and Dennis (40) bought a home together in Zoetermeer six years ago and took out the mortgage together. They are separating; Marloes will stay in the home with the children. Dennis agrees with her that from now on she will pay all the costs and that he is thereby free of the debt. He asks whether he is still liable to the bank for anything. What applies?", [["Both remain jointly and severally liable for the whole debt until the lender releases Dennis", "The lender can claim the full amount from either of them; their mutual arrangements do not bind the bank."], ["Because of the mutual agreement with Marloes, Dennis is automatically no longer liable to the bank", "An agreement between the partners works only between them; release from joint and several liability requires the lender."], ["Each is liable to the bank for only half of the debt", "Between themselves they can divide the debt, but towards the lender they are jointly and severally liable."], ["The mortgage lapses at the end of the relationship and Marloes must take out a new one", "The end of a relationship leaves the existing credit agreement intact."]], "1f.4"],
["Ad (58) is a lorry driver and wants to move with his wife Thea (57) to a single-storey home in Veenendaal. They need a mortgage of €180,000 with a term of thirty years. In about nine years Ad reaches the AOW (state pension) age and his income falls. Thea does not work and has built up no pension of her own. What must the adviser at least map out?", [["Whether the costs are affordable after retirement with their expected AOW and pension income", "With a term running beyond the AOW (state pension) age, affordability must also be assessed for the period after retirement."], ["Whether they can buy a second home before retirement with the equity in their home", "A second home is not a relevant point of attention here; what matters is affordability after retirement."], ["Whether the mortgage interest rate falls automatically once the AOW (state pension) age is reached", "The interest rate does not depend on the client's age."], ["Whether the Hillen Act takes over the mortgage interest in whole or in part after retirement", "The Hillen Act concerns a deduction where there is no or a small owner-occupied home debt and does not pay interest."]], "1h.1"],
["How should the adviser deal with risks such as death, incapacity for work and unemployment in the mortgage advice?", [["Calculate the consequences, discuss them, record the choice", "Suitable advice shows what happens and which solutions exist; the client chooses consciously and this is recorded."], ["Mention them only if the client asks about them himself", "An adviser must investigate and discuss risks on his own initiative."], ["Always make insurance mandatory for every risk", "Insurance is not always necessary; a buffer or acceptance of the risk may also be appropriate."], ["Leave it to the lender, because the lender tests creditworthiness", "The creditworthiness test does not replace the adviser's risk analysis."]], "2d.2"],
["What effect does a favourable energy label of the home have on borrowing capacity under the TRHK?", [["Depending on the label, extra borrowing room is possible", "The TRHK gives extra borrowing room for more energy-efficient homes, because the energy costs there are lower."], ["A favourable label raises the maximum LTV to 125%", "The energy label does not raise the LTV to such a level."], ["The energy label has no effect on the lending standards", "The TRHK does take the energy label into account."], ["With a favourable label the test rate no longer applies", "The label affects the loan amount, not the test rate method."]], "1a.2"],
["A client wants to co-finance energy-saving measures, such as solar panels and insulation. What is possible under the lending standards?", [["Under conditions, a mortgage above 100% of the market value for those measures", "Energy-saving measures form an exception to the main rule of an LTV of at most 100%."], ["Only if the measures were installed before the purchase and included in the valuation", "Measures still to be installed can also be co-financed, often through a construction deposit account."], ["Never, because the LTV is 100% without exceptions", "The TRHK in fact has an exception for energy-saving measures."], ["Only through a personal loan outside the mortgage", "Co-financing within the mortgage is in fact possible."]], "1a.2"],
["When assessing a mortgage application, the BKR (Dutch credit registration bureau) shows that the client had a payment arrear on a credit card a few years ago, which has been registered. What is correct?", [["The lender takes the registration into account in its assessment, which may lead to rejection", "An arrears registration says something about payment behaviour; the lender itself assesses whether lending is responsible."], ["The BKR itself decides whether the client may get the mortgage", "The BKR only registers data; it takes no credit decisions."], ["The registration disappears automatically as soon as the client applies for a mortgage with a lender", "An application has no effect on the existence or retention period of a registration."], ["Only arrears on a previous mortgage may be taken into account", "Arrears on other credit also say something about payment behaviour and are taken into account."]], "1e.6"],
["A client finances sustainability improvements through the mortgage and the amount is paid into a construction deposit account. What is the function of that deposit account?", [["Payment is made only on invoices for the agreed measures", "The deposit account ensures that the money is used for the measures that improve the value or energy efficiency."], ["The money is paid directly into the client's private account", "That is precisely what the construction deposit account prevents."], ["The money is invested until the fixed-rate period ends", "A construction deposit account is not an investment account."], ["The money serves as a buffer for payment arrears", "A construction deposit account is intended for the renovation, not for arrears."]], "1e.3"],
["What does the Mortgage Credit Directive (MCD) regulate regarding tying practices (koppelverkoop)?", [["Tying is in principle prohibited; bundling (separately available) is permitted", "With tying, the credit is not available separately; that is prohibited. A bundle whose components can also be obtained separately is permitted."], ["Tying is always permitted if the consumer has received an ESIS with all product combinations in advance", "An ESIS does not make prohibited tying permissible."], ["Every combination of a mortgage with another product is prohibited", "Bundled sale is permitted."], ["Tying is prohibited only for mortgages with NHG (National Mortgage Guarantee)", "The prohibition follows from the directive and does not apply only to NHG."]], "1a.3"],
["On what may the creditworthiness assessment not mainly be based under the Mortgage Credit Directive?", [["On the expectation that the value of the home will rise", "The test must look mainly at the consumer's ability to meet his obligations, not at expected increases in value."], ["On the consumer's current income from employment or a business", "Income is in fact a core element of the assessment."], ["On the consumer's fixed costs and existing obligations", "Fixed costs are part of a proper assessment of the ability to pay."], ["On the information from the BKR (Dutch credit registration bureau) register", "BKR information is an important source and is in fact used."]], "1a.3"],
["A client takes out a mortgage directly from a bank, with advice from an adviser employed by that bank. What applies to the costs of that advice?", [["The bank charges the costs for advice and distribution separately, just like an intermediary", "Because of the commission ban and the rules on cost transparency, direct providers too may not hide these costs in the product price."], ["With a bank the advice costs are always included in the mortgage interest rate and are therefore not visible", "Costs for advice and distribution may not be hidden in the interest rate; they must be separately visible."], ["Advice by a bank employee is free, because the bank receives no commission", "The bank may also charge costs for advice; the commission ban in fact makes those costs visible."], ["The costs are lower than with an intermediary, because the law prescribes that", "The law does not prescribe lower costs for direct providers; they must state the costs separately and in advance."]], "1e.8"],
["May a mortgage adviser receive commission from the lender for arranging a mortgage for a consumer?", [["No, a commission ban has applied to mortgages since 2013", "Since 2013 an adviser may not receive commission from the provider for mortgages for consumers."], ["Yes, provided the commission is stated in the ESIS", "Stating it does not make the commission permitted."], ["Yes, if the commission is lower than 1% of the principal", "There is no threshold; commission is prohibited."], ["Only if the client gives written consent", "The client's consent does not lift the ban."]], "1e.8"],
["Jasper (32) and Mirthe (31) have found their dream home in Rotterdam and want to borrow the maximum amount. The inventory shows that afterwards they will have no room left to save and no buffer remaining. Mirthe expects a child within two years and then wants to work less. They say they accept those risks. What does the adviser's duty of care require?", [["That he discusses the risks, gives suitable advice and records the conversation and their choice", "The adviser must advise the client suitably, explain the risks and record what was discussed and decided."], ["That he carries out their wish without further discussion, because they are themselves responsible for the choice", "The duty of care requires own, suitable advice; simply carrying out the client's wish is insufficient."], ["That he refers them to another adviser, because he may not advise on this loan", "Referral is not necessary; he must advise suitably himself."], ["That he asks the AFM in advance for permission to borrow more than his advice", "The AFM gives no permission for individual advice."]], "2e.2"],
["Why do lenders actively approach clients with an interest-only mortgage?", [["To point out to them the risk of an unaffordable debt at the end", "The AFM has asked providers to point out this risk to clients in good time, in line with their duty of care."], ["To compulsorily convert the interest-only loan into an annuity loan", "A compulsory conversion is not a consequence of this approach."], ["To withdraw the client's transitional rule", "A lender cannot withdraw the tax transitional rule."], ["To have the home valued again for the WOZ value", "The WOZ value is set by the municipality."]], "3e.3"],
["Viktor (45) wants to buy an apartment in Amsterdam for €600,000 and contributes €250,000 of his own money. He cannot explain well where this money comes from; according to him it was saved via friends abroad. The amount has only recently been in his account, after several cash deposits. His income as a self-employed consultant is modest. What does the Wwft require of the lender?", [["Investigate the origin of the money and report an unusual transaction to FIU-Nederland", "Where the origin is unclear, the institution must carry out further investigation and, if necessary, report an unusual transaction."], ["Accept the money, because own contribution in fact lowers the bank's credit risk", "A lower credit risk does not remove the Wwft duty to investigate the origin."], ["Immediately report the client to the police and reject the application without explanation", "The Wwft requires a report to FIU-Nederland, not a report to the police."], ["Ask the client first to obtain an official statement of origin from the AFM or the Dutch Tax and Customs Administration", "The AFM and the Dutch Tax and Customs Administration do not issue statements of origin; the institution investigates this itself."]], "4a.1"],
["A Wwft institution has reported an unusual transaction of a client. May it inform the client about this?", [["No, the institution may not tell the client that a report has been made", "The Wwft prohibits informing the client about a report, so that the investigation is not frustrated."], ["Yes, under the GDPR (AVG) the client always has a right of access to the report", "The right of access under the GDPR (AVG) does not apply here; the Wwft duty of confidentiality takes precedence."], ["Yes, but only in writing and only after the transaction has been completed, to the client himself", "Even after completion, the client may not be informed of the report."], ["Only if the client has a mortgage with NHG (National Mortgage Guarantee)", "NHG has no influence whatsoever on the duty of confidentiality."]], "1a.3"],
["Sem (33) and Laura (37) are buying a home together in Amersfoort, each for half. It is the first home they have bought and they will live in it themselves. The purchase price is below the property value limit for the first-time buyer exemption. Sem works as an electrician, Laura as an HR adviser. What applies to transfer tax?", [["Sem is exempt for his half; Laura pays the reduced rate on her half", "The first-time buyer exemption is assessed per acquirer; Laura does not meet the age requirement of under 35."], ["Both are exempt, because one of them is under 35", "The exemption applies per person, not per household."], ["Both pay the reduced rate on their own half, because Laura is over 35", "Sem does not lose his exemption because Laura does not meet it."], ["Both pay the general rate, because they are buying a home together", "Buying together is no reason for the general rate; they will live in the home themselves."]], "1a.1"],
["Ilse (28) is a dental assistant and is buying her first home, a family house in Hoorn. She will live in it herself and has never used the first-time buyer exemption. The purchase price is just above the property value limit for that exemption. She hopes she only has to pay on the excess. What is the consequence?", [["She is not entitled to the exemption and pays the reduced rate on the entire purchase price", "The property value limit is a hard limit: above it the exemption lapses entirely and the reduced rate for owner-occupation applies."], ["She pays transfer tax only on the part above the property value limit", "The exemption does not work as a threshold; above the limit it lapses completely."], ["She pays the general rate on the entire purchase price, because the property value limit has been exceeded", "Because she will live in the home herself, the reduced rate applies and not the general rate."], ["She keeps the exemption if she renovates the home within a year after purchase", "A renovation after purchase has no effect on the exemption."]], "1a.1"],
["A client has an owner-occupied home endowment policy (kapitaalverzekering eigen woning, KEW) from 2008 that is pledged to his mortgage. He wants to surrender the policy before the end date and use the money for a new car; the mortgage stays the same. What is the tax consequence?", [["The exemption lapses and the interest component of the surrender value is taxed in box 1", "The exemption for a KEW applies only if the payout is used to repay the owner-occupied home debt; otherwise the interest component is taxed."], ["The surrender value is fully exempt, because the policy has been running for well over fifteen years", "The term alone is not enough; the payout must also be used to repay the owner-occupied home debt."], ["The surrender value falls in box 3 as an asset and is otherwise untaxed", "On surrender without repayment the interest component is taxed in box 1, not only as an asset in box 3."], ["The premiums paid are still allowed as a deduction in box 1", "Premiums for a KEW have never been deductible, not even on surrender."]], "1e.12"],
["Bas (35) is an account manager with €65,000 gross per year and Merel (34) is a part-time teacher with €30,000 gross per year. They want to buy a family home in Amersfoort. Merel has heard that the second income counts only partly for the mortgage. They ask their adviser how that works. How does Merel's income count towards the test income under the lending standards?", [["In full, like the highest income; the restriction on the second income has lapsed", "Since 2024 the income of the lower-earning partner counts in full towards the test income."], ["For half, to absorb the risk of the second income dropping out, on the lender's side", "Partial weighting applied in the past; since 2024 the second income counts in full."], ["Not at all; only the highest income determines their maximum mortgage", "The second income also counts towards the test income."], ["Only if both partners have a permanent contract of indefinite duration", "A permanent contract is not a condition for counting the second income."]], "1i.4"],
["What normally happens on the day of the transfer of ownership at the notary?", [["The deeds are signed and the notary pays the seller via the third-party funds account", "The notary receives the money in advance from the lender and the buyer, has the deeds signed, pays the seller and has the deeds registered."], ["The buyer pays the purchase price to the seller in cash in the presence of the estate agent", "Cash payment is unusual; the money goes through the notary."], ["The lender pays the loan into the buyer's private account, and the buyer pays the seller", "The mortgage amount goes to the notary's third-party funds account, not to the buyer."], ["Only the purchase agreement is signed; delivery follows after a few months", "The purchase agreement was already concluded earlier; delivery takes place at the notary."]], "1b.7"],
["How does the financing burden percentage in the TRHK relate in general to the level of the test income?", [["With a higher income the percentage is higher", "Someone who earns more has relatively more left after the fixed basic expenditure and can therefore spend a larger part of his income on housing costs."], ["The percentage is the same for all incomes, only the interest rate makes a difference", "The tables in fact vary with income; a fixed percentage for everyone would burden lower incomes too heavily."], ["With a higher income the percentage is lower, because the tax burden rises", "The percentage rises with income; the higher tax burden has already been factored in and does not reverse that."], ["The percentage depends only on the applicant's age", "Age plays a role only around the AOW (state pension) age; the level of income and the test rate determine the percentage."]], "1a.2"],
["Rick (37) works as an IT administrator and has a test income of €60,000. He wants to buy an apartment on his own in Leeuwarden. At his income and the applicable test rate, the table gives a financing burden percentage of 25%. He has no other financial obligations. What is his maximum gross monthly payment for interest and repayment?", [["€1,250 per month", "€60,000 × 25% = €15,000 per year, divided by 12 is €1,250 per month."], ["€1,500 per month", "This assumes 30% instead of 25%."], ["€15,000 per month", "€15,000 is the maximum annual cost, not the monthly cost."], ["€937.50 per month", "This is 75% of the correct monthly payment; the percentage has been applied wrongly."]], "1i.4"],
["What must a lender do if the creditworthiness assessment shows that the requested mortgage is not responsible?", [["Not grant the credit in this form, not even at the client's request", "The Wft prohibits over-lending: if the credit proves irresponsible, the lender may not enter into it."], ["Grant the credit if the client signs a declaration that he accepts the risk", "A waiver by the client does not lift the prohibition on over-lending; the responsibility lies with the lender."], ["Grant the credit at a higher interest rate as compensation for the risk", "A higher interest rate only makes an irresponsible loan heavier and is no solution to over-lending."], ["Grant the credit, but report this to the AFM within a month", "There is no reporting route that makes over-lending permissible; the credit may then not be granted."]], "1a.3"],
["Nadia (30) works as a marketing adviser and wants to buy a home in Utrecht with her partner Tom (31). She drives a private lease car for which she pays a fixed amount every month; the contract still has three years to run. Tom thinks this makes no difference to the mortgage application, because it is a rental contract. How does the lender in principle treat the private lease?", [["The lease instalment counts as a fixed obligation and reduces the borrowing capacity", "Private lease is a fixed monthly obligation that weighs on the budget and is therefore taken into account."], ["Private lease is legally the hire of a car and therefore always remains outside the test", "Even though it is legally hire, the fixed cost weighs on the ability to pay and therefore counts."], ["Only the residual value of the car at the end of the contract counts", "With private lease there is no residual value for the client; what counts is the monthly instalment."], ["The lease car increases the borrowing capacity, because it counts as an asset", "The car is owned by the lease company, not by the client."]], "1i.4"],
["A client buys a new-build home from a project developer. On what is the value of the home for the LTV test usually based for new build?", [["On the purchase/construction price including extras", "For new build, the price free on name (vrij-op-naamprijs) plus the extras serves as the value; a valuation is then usually not needed."], ["On the WOZ value that the municipality sets after delivery", "The WOZ value does not yet exist at purchase and is not used for the LTV test."], ["On the land value, because the structure still has to be built", "The financing relates to the complete home; the land value alone would greatly underestimate the value."], ["On an average of comparable existing homes in the neighbourhood", "Such an average is not a test measure; for new build the purchase/construction price with extras is the starting point."]], "1a.2"],
["What should a lender do towards the client around the end of a fixed-rate period?", [["Inform the client in good time in advance about the interest reset and the new offer", "This allows the client to choose a new period in time or compare with other providers."], ["Automatically extend the interest rate for the same period without informing the client", "Tacit extension without information would undermine the client's freedom of choice; the lender is in fact expected to provide timely information."], ["Require the client to obtain new mortgage advice from a recognised adviser", "An interest reset requires no new advice process; the client may choose himself."], ["Call in the loan in full if the client does not respond within a week", "The end of the fixed-rate period is not a ground for calling in the loan; the loan simply continues."]], "1a.6"],
["A client receives a binding mortgage offer from his lender. What applies under the rules for mortgage credit to consumers?", [["It stays valid for at least fourteen days, to compare and reflect", "This reflection period under the Mortgage Credit Directive gives the consumer time to assess the offer before being bound."], ["The client must accept the offer within three days, otherwise it lapses", "Three days is the cooling-off period for the purchase deed of a home, not the validity of a mortgage offer."], ["The lender may withdraw the offer at any time if the interest rate rises", "During the reflection period the lender cannot unilaterally withdraw the offer because of an interest rate rise."], ["A binding offer is valid only after the notary has executed the deed", "The offer precedes the deed; the notary executes the deed on the basis of the accepted offer."]], "1a.6"],
["A client borrows €200,000 on an annuity basis over 30 years at 4% interest. The gross monthly payment is approximately €954.83. How much does he repay in the first month?", [["Approximately €288.16", "The interest in month 1 is €200,000 × 4% / 12 = €666.67; the rest of the annuity, €288.16, is repayment."], ["Approximately €555.56", "This is the repayment on a linear loan (€200,000 / 360); with an annuity the repayment is lower at the start."], ["Approximately €666.67", "This is the interest portion of the first month, not the repayment portion."], ["Approximately €954.83", "This is the full gross monthly payment; most of it is still interest."]], "1i.3"],
["A client has a linear mortgage of €360,000 with a term of 30 years and an interest rate of 4.2%. By how much does the gross monthly payment fall each month?", [["€3.50", "He repays €1,000 every month (€360,000 / 360); the interest on that is €1,000 × 4.2% / 12 = €3.50 less per month."], ["€1,000.00", "This is the fixed monthly repayment amount, not the fall in the monthly payment."], ["€42.00", "This is the annual interest on €1,000; per month the interest falls by one twelfth of that."], ["€0.00, the gross monthly payment stays the same as long as the interest rate is fixed", "Constant gross costs go with an annuity; with a linear loan the costs fall because the debt decreases."]], "1i.3"],
["What is characteristic of a traditional savings mortgage linked to a savings insurance policy?", [["The savings part earns interest equal to the mortgage rate", "Because the savings part and the loan have the same return, the construction works out net comparably to an annuity."], ["The savings part is invested in shares with a fluctuating return", "Investing in shares is characteristic of the investment mortgage, not of the savings mortgage."], ["The client repays the loan directly every month", "With a savings mortgage the loan remains outstanding and is repaid in one go at the end through the savings part."], ["The interest on the savings part is always fixed for the whole term", "The savings interest follows the mortgage interest and can therefore change on an interest reset."]], "1e.2"],
["What is characteristic of a credit mortgage (krediethypotheek; mortgage-backed revolving credit)?", [["The client can draw money and pay it back again within an agreed limit", "A credit mortgage works like a revolving credit with the home as security; the interest rate is often variable."], ["The client receives the whole amount at once and repays in fixed instalments", "That describes an ordinary annuity or linear loan, not a revolving credit facility."], ["No interest is ever charged as long as the client draws nothing", "The client pays no interest on the undrawn part, but that is a consequence and not what characterises the form."], ["The loan is automatically repaid from a linked life insurance policy", "Linkage to an insurance policy is characteristic of a life mortgage (levenhypotheek), not of a credit mortgage."]], "1i.3"],
["Truus (74) is a widow and lives in a mortgage-free home in Amstelveen. Her AOW (state pension) and small pension are just enough for the fixed costs, but she wants to have her bathroom adapted and help her grandchildren. A provider offers her an equity release mortgage (verzilverhypotheek) under which she pays no monthly payments and the interest is added to the debt. Her daughter asks the adviser what the biggest risk is. Which risk should the adviser mainly discuss?", [["The debt grows through the added interest and can eat up the equity in the home", "Because interest on interest is added, the debt can rise quickly and reduce the equity for her or her heirs."], ["The monthly payments can rise immediately and sharply if interest rates go up", "With an equity release mortgage she pays no monthly payments; the interest is added to the debt."], ["She must repay the loan in full in one go after ten years", "An equity release mortgage is usually repaid only on sale or death."], ["The home becomes the lender's property immediately after the equity release mortgage is taken out", "She remains the owner; the lender only receives a mortgage right."]], "1i.2"],
["Kim (36) and Ali (38) took out a mortgage four years ago with an interest rate of 2% that is still fixed for six years. With their second child on the way they are buying a larger home in Haarlem. The interest rate is now considerably higher than their current rate. They would like to keep their low rate for the amount they already borrow. Which product condition makes that possible?", [["A portability scheme (meeneemregeling) in their current terms", "With a portability scheme the existing loan, with its interest rate and remaining fixed-rate period, can be taken along to the new home."], ["An interest rate reduction guarantee in the offer for the new home", "An interest rate reduction guarantee concerns a fall in rates during the offer period, not keeping an old rate."], ["A bridging loan on their current home until the sale", "A bridging loan makes equity temporarily available, but does not preserve the interest rate."], ["A capped rate on the new loan part for the larger home", "A capped rate limits a variable interest rate and says nothing about taking the old rate along."]], "1h.6"],
["What is a starter loan (starterslening), as offered by some municipalities?", [["A supplementary loan alongside the first mortgage on the home", "The starter loan comes on top of the regular mortgage and often has favourable terms in the first years."], ["A subsidy that the first-time buyer does not have to repay", "It is a loan that does have to be repaid, even though the first years are often free of interest and repayment."], ["A mortgage that replaces the requirement for NHG (National Mortgage Guarantee)", "A starter loan is supplementary and does not replace NHG; they are often used together."], ["An exemption from transfer tax for young buyers", "The first-time buyer exemption is a tax rule; the starter loan is a financing product."]], "1b.6"],
["Hans (63) has had an interest-only loan part of €120,000 on his home in Assen since 2010. He wants to reduce his mortgage considerably before retirement and is considering converting this part into an annuity loan. He is afraid he will lose his interest deduction by doing so. His adviser finds out what the tax consequences are. What is correct for tax purposes?", [["The loan part remains owner-occupied home debt and the interest remains deductible", "Converting a debt under the transitional rule to a repaying form leaves the interest deduction intact."], ["After the conversion the loan part falls in box 3 from then on", "Repaying does not turn the loan into a box 3 debt."], ["He gets a new thirty-year term from the date of conversion", "The existing term for interest deduction continues; a conversion does not start a new term."], ["The conversion is permitted only with permission from the Dutch Tax and Customs Administration", "No permission from the Dutch Tax and Customs Administration is needed for a conversion."]], "1a.1"],
["When is a home an owner-occupied home for tax purposes within the meaning of the Income Tax Act 2001?", [["If it is permanently available to him and his household as main residence", "The main residence criterion is the core of the owner-occupied home regime (usually by virtue of ownership); a second home or investment property falls outside it."], ["If the client is registered there, even if he does not actually live there", "Registration in the BRP (Personal Records Database) is an indication, but the actual main residence is decisive."], ["If the home is financed with a mortgage, regardless of who lives in it", "Financing with a mortgage does not make a home an owner-occupied home; what matters is the main residence."], ["If the client stays there at least three months a year", "A minimum number of months is not the criterion; it must be the main residence."]], "1a.1"],
["A client has had a mortgage on his owner-occupied home since 1995. From which moment does the 30-year term for interest deduction run on this debt?", [["From 1 January 2001", "For debts from before the Income Tax Act 2001 the term started running on 1 January 2001; the deduction therefore ends at the end of 2030 at the latest."], ["From the date it was taken out in 1995", "The 30-year term did not yet exist in 1995; for existing debts it started on 1 January 2001."], ["From 1 January 2013", "The repayment requirement came into force in 2013, but the 30-year term for old debts had already been running since 2001."], ["No term applies; old debts have unlimited deduction", "Debts from before 2001 are also subject to the maximum deduction period of 30 years."]], "1a.1"],
["A client buys a home. Which notary costs are directly deductible as financing costs in box 1?", [["The notary costs for drawing up the mortgage deed", "The costs of the mortgage deed are costs of taking out the loan and are therefore deductible."], ["The notary costs for the deed of transfer", "The deed of transfer belongs to the acquisition of the home; those costs are not deductible, but can be financed."], ["The transfer tax that the notary collects on behalf of the state", "Transfer tax is part of the acquisition costs and is not deductible."], ["The Land Registry registration fee for the transfer of ownership", "Costs for registering the transfer are acquisition costs and are not directly deductible."]], "1e.7"],
["A client co-finances the purchase costs, such as transfer tax and delivery costs, in the mortgage. What is correct for tax purposes?", [["The loan part for the purchase costs can be owner-occupied home debt", "Acquisition costs count towards the owner-occupied home debt; the interest on it is deductible if the other requirements are met."], ["The costs themselves are directly deductible and the loan part falls in box 3", "It is the other way round: the costs are not deductible, but the loan part can be owner-occupied home debt."], ["Purchase costs may never be borrowed, not even outside the TRHK", "For tax purposes it is possible; the LTV standard does limit how much may be borrowed above the market value."], ["The loan part is deductible only if it is interest-only", "An interest-only loan after 2012 in fact does not meet the repayment requirement and gives no deduction."]], "1e.7"],
["At what rate can mortgage interest on an owner-occupied home debt be deducted at most for a client with a high income?", [["At a statutory capped percentage that is lower than the top rate", "The rate at which deductions for the owner-occupied home are offset has been phased down and capped; even income in the highest bracket yields no more."], ["At the top rate, because his income falls in the highest bracket", "Deduction at the top rate has been phased out; the benefit is capped."], ["At the box 3 rate on the balance of assets and debts", "The owner-occupied home falls in box 1; the box 3 rate plays no role in the interest deduction."], ["At a fixed percentage of the WOZ value of the home", "A percentage of the WOZ value is the notional rental value, not a deduction rate."]], "1h.4"],
["What applies to an owner-occupied home with a WOZ value above the limit above which the higher notional rental value (the 'villataks', villa tax) applies?", [["A higher notional rental value percentage on the excess", "For expensive homes the notional rental value is increased on the excess above the limit, in order to limit the net deduction."], ["The notional rental value lapses on the whole WOZ value", "The notional rental value does not lapse; above the limit it is in fact higher."], ["Mortgage interest is no longer deductible above that limit", "The interest deduction simply remains; only the notional rental value is increased above the limit."], ["Above that limit the home falls entirely in box 3", "An expensive home also remains an owner-occupied home in box 1 if it is the main residence."]], "1h.4"],
["Michiel (45) and Anouk (43) are married and are getting divorced. In March 2026 Michiel leaves their joint home in Gouda and goes to rent; Anouk stays there with the children. For the time being Michiel pays half of the mortgage interest. He asks whether he may still deduct that interest. For how long can he still treat the home as an owner-occupied home for tax purposes?", [["A maximum of two years after he leaves, as long as Anouk keeps living there as (former) partner", "The departing partner can treat the home as an owner-occupied home for a maximum of two years as long as the (former) partner remains living there."], ["Until the divorce is registered in the registers; after that his share of the home falls directly in box 3", "Registration of the divorce is not the decisive moment; the law has a period of two years."], ["As long as he remains a co-owner, even if the home is later let", "If let, the home is not an owner-occupied home; co-ownership alone is not enough."], ["Three years, as with an empty home that is for sale", "The three-year period belongs to vacancy; on divorce a maximum of two years applies."]], "1a.1"],
["A client wants to use a gift from his parents to repay his owner-occupied home debt. What has applied since 1 January 2024 to the gift tax exemption for the owner-occupied home?", [["It was abolished completely as of 1 January 2024", "The increased exemption for the owner-occupied home (the 'jubelton') has no longer existed since 2024."], ["It was increased for children under 40", "The exemption was not increased but abolished completely."], ["It now applies only to repayment and no longer to purchase", "The exemption has lapsed for all owner-occupied home uses, including repayment."], ["Since 2024 it may be spread over three years", "Spreading was a feature of the old scheme; since 2024 the entire exemption no longer exists."]], "1a.1"],
["Robin (29) wants to buy an apartment in Groningen with NHG (National Mortgage Guarantee). He has recently started working in Rotterdam and plans to let the home to students straight away. In a few years he may want to live in it himself. He hopes to get a lower interest rate with NHG. What is correct?", [["NHG is not possible, because the home must be for owner-occupation", "NHG is intended for homes that the consumer will live in himself."], ["NHG is possible if the rental income fully covers the monthly payments", "Coverage by rental income changes nothing about the requirement of owner-occupation."], ["NHG is possible, but at a double guarantee fee", "A double fee for letting does not exist; NHG is then not possible."], ["NHG is possible if the tenants also sign an NHG statement", "A statement from tenants does not exist; owner-occupation is required."]], "1b.3"],
["Where are the conditions that an NHG (National Mortgage Guarantee) loan must meet set out?", [["In the NHG Terms and Conditions of Stichting WEW", "Stichting WEW sets these conditions and adjusts them periodically, including the cost limit."], ["In the Code of Conduct for Mortgage Financing", "The GHF contains minimum requirements for offers and terms, not the NHG standards."], ["In the Income Tax Act 2001", "The Income Tax Act regulates the tax treatment, not the conditions for the guarantee."], ["In the Conduct Supervision of Financial Undertakings Decree", "That decree contains Wft conduct rules; the NHG conditions are set under private law by the foundation."]], "1b.3"],
["A client wants to co-finance energy-saving measures with NHG (National Mortgage Guarantee) as well. What applies to the NHG cost limit?", [["It may be increased for energy-saving measures", "The NHG Terms and Conditions offer extra room above the ordinary cost limit for energy-saving measures."], ["It then no longer applies; the whole amount falls under NHG", "A maximum continues to apply; the extra room for sustainability improvements is capped."], ["It becomes lower, because sustainable homes carry less risk", "Sustainability improvements do not lead to a lower limit; the scheme in fact encourages extra room."], ["Sustainability improvements can never be financed with NHG", "Sustainability improvements can in fact be co-financed with NHG under conditions."]], "1b.3"],
["In which register must a valuer who values a home for mortgage financing in the Netherlands be registered?", [["In the Dutch Register of Real Estate Appraisers (NRVT)", "For mortgages, lenders and validation institutes accept only reports from valuers registered in the NRVT (Dutch Register of Real Estate Appraisers, Nederlands Register Vastgoed Taxateurs)."], ["In the AFM register of financial service providers", "The AFM register is for financial service providers; valuers are in the NRVT."], ["In the Land Registry", "The Land Registry registers immovable property and rights, not valuers."], ["In the Kifid register", "Kifid handles complaints about financial services and keeps no register of valuers."]], "1b.3"],
["A client buys a new-build home for which the purchase agreement contains an anti-speculation clause. What does this mean for him?", [["For a certain period he may not sell or let the home without permission or a penalty", "The clause is meant to prevent buyers from quickly reselling at a profit or starting to let; it temporarily limits saleability."], ["He may never sell the home for more than the purchase price", "The clause applies for a certain period, not forever."], ["He may not use the home as collateral for a mortgage", "Financing with a mortgage remains possible; the clause concerns resale and letting."], ["He gets a reduction in transfer tax as long as he does not sell the home within the agreed period", "The clause has no effect on transfer tax; it only restricts resale and letting."]], "1f.1"],
["Why does a lender not, as a rule, use the WOZ value as the basis for the LTV for a new financing?", [["Because it serves for tax assessment and lags behind the market", "The WOZ value lags behind the market and is not intended as a current market value for financing."], ["Because the WOZ value is always higher than the market value", "The WOZ value can come out lower or higher; the problem is that it is not current and not intended for financing."], ["Because the AFM prohibits the use of the WOZ value for all mortgages", "There is no general prohibition; some lenders do use the WOZ value for limited increases."], ["Because the WOZ value is set only for rented homes", "The municipality sets a WOZ value for all homes, including owner-occupied homes."]], "1b.3"],
["A client buys a building plot and has a contractor build a home on it under his own management. What is characteristic of the financing?", [["Money goes into a construction deposit account, paid out as building progresses", "With self-build the client pays the contractor in instalments; through the construction deposit account money is released only on invoices for progress."], ["The whole loan is paid at the notary directly into the client's private account", "The construction amount is not paid to the client in one go, but through the deposit account on the basis of invoices."], ["A mortgage is possible only after the home is completely finished", "The plot can already serve as collateral; the expected value after construction is included in the assessment."], ["With self-build the risk of extras and delays always lies with the lender", "Extras and delays are for the client's account; a financial buffer is therefore sensible."]], "1f.2"],
["When does ownership of a home legally pass to the buyer on purchase?", [["On registration of the deed in the Land Registry", "Transfer of immovable property requires a notarial deed and registration in the Land Registry."], ["On signing the purchase agreement at the estate agent", "The purchase agreement obliges delivery, but does not yet transfer ownership."], ["On payment of the security deposit or bank guarantee", "The security deposit is security for the seller; ownership passes only on delivery."], ["On handing over of the keys by the seller", "Handing over the keys is physical delivery, not legal transfer of ownership."]], "1b.5"],
["A private buyer signs the purchase deed for a home on Monday and receives it the same day. What applies?", [["Three days' statutory cooling-off period after receiving the deed", "The Dutch Civil Code gives a consumer buying a home three days' cooling-off period after the purchase deed has been handed to him."], ["He has fourteen days' cooling-off period, as with a distance purchase", "Fourteen days applies to a distance purchase; for a home purchase the cooling-off period is three days."], ["He can only dissolve if the financing does not come through", "A financing condition is a separate dissolving condition; the cooling-off period is separate from it."], ["He has no cooling-off period, because he signed in person", "Even when signing in person, a private buyer has a statutory cooling-off period."]], "1b.9"],
["What is a statutory requirement for the purchase of a home by a consumer?", [["The purchase agreement must be in writing", "For the purchase of a home by a consumer, the purchase is concluded only once it has been recorded in writing."], ["The purchase agreement must be drawn up by a notary", "The purchase deed is often drawn up by an estate agent; only the deed of transfer is notarial."], ["The purchase price must be approved by the valuer", "A valuation is not a condition for a valid purchase agreement."], ["The buyer must submit a mortgage offer on signing", "An offer is not a condition for the purchase; a financing condition may serve for that."]], "1b.5"],
["Femke (31) and Luuk (33) have bought a home in Zwolle with a financing condition until 1 December. On 20 November the lender rejects their application, because Luuk's temporary contract is not taken into account. A second lender cannot take a decision before 1 December. The seller does not yet know anything about it. What can they do?", [["Dissolve before 1 December by invoking the condition and enclosing the rejection", "Invoking the financing condition must be done in good time and in accordance with the purchase deed, usually with proof of the rejection."], ["Nothing; the purchase is fixed as soon as the statutory cooling-off period has passed", "After the cooling-off period the buyer can still invoke a dissolving condition."], ["Dissolve, but only on payment of the penalty from the purchase deed", "No penalty is due if the condition is rightly invoked."], ["Still dissolve the purchase after 1 December as soon as the second bank also rejects", "After the agreed date the condition has expired and dissolving on that ground is no longer possible."]], "1b.9"],
["What is the purpose of the bank guarantee or security deposit that a buyer provides after signing the purchase deed?", [["Security for the seller in the event of default by the buyer", "If the buyer fails to perform, the seller can recover a penalty from the security deposit or bank guarantee."], ["A first repayment on the new mortgage", "The security deposit is not a repayment; it is set off against the purchase price on delivery."], ["Payment of the estate agent's brokerage fee owed by the seller", "The brokerage fee is an arrangement between seller and estate agent and is separate from the security deposit."], ["A surety for the NHG (National Mortgage Guarantee) guarantee fee", "The NHG fee is paid on the financing and has nothing to do with the security deposit."]], "1b.9"],
["What does the notary use a third-party funds account for in a home transaction?", [["To settle the funds of all parties safely", "The money is kept separate from the notary's own assets and is paid out only after the deeds have been registered."], ["To collect the notary costs in advance from the buyer", "The account is not intended for the notary's own costs but for funds of third parties."], ["To let the transfer tax earn a return for a year", "The notary remits transfer tax and may not use third-party money for his own return."], ["To manage the loan during its term on behalf of the lender", "After settlement the notary has no further role in managing the loan."]], "1b.7"],
["What is in principle the difference between a surety and a co-debtor on a mortgage loan?", [["A surety can be called on only when the principal debtor fails; a co-debtor directly for the whole debt", "A surety stands guarantor for another person's debt; a co-debtor is himself a jointly and severally liable debtor."], ["A surety is directly liable for the whole debt; a co-debtor only if the principal debtor himself does not pay", "This is exactly the other way round: the co-debtor is himself the debtor, the surety stands guarantor for another."], ["A surety and a co-debtor are both liable for only half of the loan and the interest", "A co-debtor is jointly and severally liable for the whole debt, not for half."], ["A surety must always be a co-owner of the home; a co-debtor never needs to be", "A surety need not be an owner; a co-debtor may or may not be a co-owner."]], "1f.4"],
["What does it mean that a mortgage right is a dependent (accessory) right?", [["It exists only as long as the claim it secures exists", "A mortgage right follows the claim; once the debt has been paid (with an ordinary mortgage), the right lapses."], ["It depends on permission from the municipality", "No permission from the municipality is needed to establish a mortgage right."], ["It can exist only if there is also an NHG (National Mortgage Guarantee) guarantee", "A mortgage right also exists without NHG; NHG is a supplementary guarantee."], ["It lapses automatically when the home is sold", "On a sale, the mortgage right remains on the home until it is cancelled."]], "1f.3"],
["A client has repaid his mortgage in full. How does the mortgage registration disappear from the public registers?", [["Through cancellation (royement) in the registers", "After repayment the right must be formally cancelled in the Land Registry, otherwise the registration remains visible."], ["Automatically, as soon as the last instalment is paid", "The Land Registry does not know that the debt has been repaid; the cancellation must be requested."], ["Through a notification from the client to the municipality", "The municipality does not keep the mortgage registers; the Land Registry does."], ["Only when the home is sold to a new owner", "Cancellation can take place immediately after repayment; there is no need to wait for a sale."]], "1j.1"],
["A mortgage deed contains a rental clause (huurbeding). What does this mean for the mortgagee?", [["On enforcement he can disregard a lease made without his consent", "The rental clause protects the enforcement value: a home without a tenant fetches more."], ["He may let the home himself as long as the client has no arrears", "The rental clause gives no right to let the home during a normal term."], ["He automatically receives part of any rental income", "The clause does not regulate sharing of rent, but restricts letting without consent."], ["The client must compulsorily let the home if he moves", "There is no obligation to let; the clause in fact prohibits letting without consent."]], "1e.4"],
["A client buys an apartment. What should the adviser pay attention to in connection with the Owners' Association (VvE), among other things?", [["The VvE contribution and the reserve fund", "High contributions or a reserve fund that is too small can greatly affect the housing costs and the saleability of the apartment."], ["Whether the VvE also pays the mortgage interest", "The VvE never pays an owner's mortgage interest; it manages the shared building."], ["Whether the VvE approves the lending standards", "A VvE has no role in an owner's creditworthiness test."], ["Whether the VvE gives permission for the mortgage deed", "No VvE permission is needed to establish a mortgage on an apartment right."]], "1a.4"],
["Jan (34) bought an apartment in Delft in his own name in 2021. In 2026 he marries Sara (32) without a prenuptial agreement. Sara moves in with him and they want to buy a larger house together later. Sara wonders whether the apartment is now also hers. What applies in principle?", [["The apartment remains Jan's and stays outside the limited community of property", "Since 2018 the limited community of property has applied; what already belonged to a spouse before the marriage remains private."], ["Through the marriage the apartment falls entirely into the community of property", "Full community applies only to marriages from before 2018."], ["The apartment is automatically put half in Sara's name", "A marriage does not automatically change the registration in the Land Registry."], ["The mortgage falls into the community, but the apartment remains Jan's", "A debt belonging to a private asset in principle also remains private."]], "1a.4"],
["Tim (36) and Lisanne (34) live together unmarried and are buying a home together in Hengelo, each for half. They have no will and no children. They want the survivor to receive the whole home when the other dies. Their adviser points out the possibilities. How can they arrange that?", [["With an accrual clause (verblijvingsbeding) in a notarial cohabitation agreement", "With an accrual clause the survivor acquires the deceased's share; without a will or clause the partner is not an heir."], ["That happens automatically, because they are both named in the mortgage deed", "The mortgage deed regulates the loan, not who receives the deceased's share."], ["By registering the home with the municipality as their joint main residence", "Registration with the municipality has no consequences under inheritance law."], ["By taking out term life insurance in the name of one of them", "Insurance yields money, but does not regulate who becomes owner of the share."]], "1a.4"],
["What does interest averaging (rentemiddeling) entail?", [["The old rate and the refinancing charge are incorporated into a new, averaged rate", "Instead of paying the charge at once, the client pays an averaged interest rate for a new period."], ["The interest rate is averaged each year with the interest rate of other clients", "Interest averaging is an individual arrangement on interim revision, not an average across clients."], ["The client pays half of the interest now and the rest at the end of the term", "Deferring interest payment is something else; with interest averaging the client simply continues to pay interest monthly."], ["The interest rate is averaged with the interest rate of the previous lender on refinancing", "Interest averaging takes place with the same lender, not on refinancing to another."]], "1e.10"],
["What mainly influences the level of a variable mortgage interest rate?", [["The short-term money market rate, such as the Euribor", "Variable rates move with the short-term rate at which banks borrow money, supplemented by surcharges for costs and risk."], ["The interest rate on ten-year government bonds", "Long-term rates are decisive for long fixed-rate periods, not for the variable rate."], ["The level of the AEX index", "Share prices do not directly determine the mortgage interest rate."], ["The annual inflation adjustment of the NHG (National Mortgage Guarantee) cost limit", "The NHG cost limit is a lending limit and not an interest rate indicator."]], "1b.2"],
["With which repayment form does the amount to be covered by term life insurance stay at the same level longest?", [["With an interest-only loan, because the debt does not fall during the term", "Without repayment the debt stays the same, and so does the amount to be covered on death."], ["With a linear loan, because the same amount is repaid on it every month", "With a linear loan the debt in fact falls quickly from the start, and so does the amount to be covered."], ["With an annuity loan, because the gross monthly payment stays the same", "An equal monthly payment does not mean the debt stays the same; the debt falls, slowly at first and faster later."], ["The amount to be covered does not depend on the repayment form, only on income", "The death risk is linked to the remaining debt, and that differs per repayment form."]], "1g.2"],
["With a normal (upward-sloping) yield curve: how does the interest rate for a fixed-rate period of 20 years generally compare with that for 5 years?", [["The rate for 20 years is generally higher, as the price of longer certainty", "With a normal yield curve, long money is more expensive; the client pays for certainty against interest rate rises."], ["The rate for 20 years is generally lower, because the bank has less administration", "Administration costs hardly determine the interest rate; with a normal curve the long rate is in fact higher."], ["The rates are always the same, the term does not matter", "Rates differ per period; that is why the choice of fixed-rate period is so important."], ["The rate for 20 years is always exactly double that for 5 years", "There is no fixed calculation rule; the difference depends on the market."]], "1b.2"],
["In which situation, under most mortgage terms, does a client not have to pay a charge for early repayment?", [["On sale and delivery of the home to a third party, e.g. when moving house", "On sale and moving house, repayment is penalty-free under the usual terms; this is in line with the GHF."], ["On refinancing to another lender because of a lower interest rate", "Refinancing during the fixed-rate period is in fact the typical situation in which a charge may be due."], ["On repayment from own savings above the penalty-free allowance", "Above the penalty-free allowance a charge may be due if the market interest rate is lower."], ["On repayment with money from a box 3 investment during the fixed-rate period", "The origin of the money makes no difference; what counts is the moment and the amount of repayment."]], "1e.10"],
["What is the penalty-free repayment allowance on a mortgage?", [["The amount the client may repay extra per year without a charge", "The size differs per provider and is often expressed as a percentage of the original principal."], ["The period after the deed in which the client can cancel the loan free of charge", "That is not a penalty-free allowance; a cooling-off period applies before entering into the loan."], ["The difference between the market value and the amount of the loan", "That difference is the equity, not the penalty-free allowance."], ["The part of the loan that may remain interest-only", "Interest-only is a repayment form; the penalty-free allowance concerns extra repayment."]], "1e.10"],
["On purchase, Olga (52) took out a mortgage with an original principal of €300,000. Under her terms she may repay an extra 10% of the original principal penalty-free each year. This year she has not yet repaid anything extra. She now wants to repay €50,000 with her bonus and savings. On what amount may a charge for early repayment be due?", [["€20,000", "Penalty-free is 10% of €300,000 = €30,000; a charge may apply on the excess of €20,000."], ["€50,000", "That is the full extra amount; the penalty-free allowance of €30,000 must be deducted."], ["€45,000", "This assumes 10% of the amount repaid instead of 10% of the original principal."], ["€0, because extra repayment is always penalty-free", "Extra repayment above the penalty-free allowance is not always penalty-free; that depends on the interest rate difference."]], "1e.10"],
["Gijs (48) repays €50,000 above the penalty-free allowance on his mortgage. His contract rate is 4.5% and is still fixed for exactly four years. His lender's current rate for a fixed-rate period of four years is 3.5%. He wants a first impression of the charge without a complicated calculation. What is the lender's loss of interest without discounting to present value?", [["€2,000", "€50,000 × 1% × 4 years = €2,000; after discounting to present value the actual charge comes out slightly lower."], ["€500", "This is the loss of interest for one year; four years remain."], ["€5,000", "This calculates with ten years instead of the remaining four years."], ["€200", "This calculates with 0.1% instead of the interest rate difference of 1 percentage point."]], "1e.10"],
["Why is the loss of interest discounted to present value when calculating the charge for early repayment?", [["Because the loss lies in the future and is paid now in one go", "A future loss is worth less today; discounting prevents the client from paying more than the actual loss."], ["Because the charge must always be paid in cash at the notary", "Discounting to present value is a calculation method, not a way of paying in cash."], ["Because otherwise the charge falls under the Wwft reporting duty", "The Wwft has nothing to do with the method of calculating the charge."], ["Because this makes the charge tax-deductible", "The tax treatment does not depend on discounting to present value."]], "1e.10"],
["Wendy (44) and Marco (46) have a mortgage of €250,000 at 4.9%, still fixed for seven years. The current rate for seven years fixed is clearly lower. Refinancing will cost them a charge for early repayment plus advice, valuation and notary costs. They ask whether it is worth it. When does interim refinancing make financial sense?", [["If the net interest advantage is greater than the charge and all ancillary costs", "Refinancing pays off only if the net advantage (after tax effect) exceeds the charge and the costs."], ["Always, because a lower interest rate is in any case more advantageous in the long term", "The charge and costs can cancel out the interest advantage."], ["Only if the new fixed-rate period is shorter than their old period", "The length of the new period does not determine whether refinancing pays off."], ["Only if they can pay the charge from their own savings", "The charge can also be co-financed under conditions; what matters is the balance of advantage and costs."]], "3e.3"],
["A seller has a mortgage with a pass-on scheme (doorgeefregeling). What does that scheme entail?", [["The buyer can take over the mortgage with its rate and terms, if the lender accepts him", "The loan passes to the buyer; the lender does test whether the buyer is creditworthy."], ["The seller may take his interest rate with him to his own new home", "That is the portability scheme (meeneem- or verhuisregeling), not the pass-on scheme."], ["The buyer automatically receives the same mortgage as the seller, without testing by the lender", "The lender continues to assess the creditworthiness of the new debtor."], ["The seller can pass on his charge for early repayment to the buyer", "A pass-on scheme concerns taking over the loan, not shifting a charge."]], "1h.6"],
["A client finances solar panels and a heat pump with an additional loan part. Why is it sensible to align the term of that loan part with the lifespan of the installations?", [["So that the loan is repaid before the installations are worn out and have to be replaced", "Otherwise the client is still repaying for installations that already have to be replaced, while a new investment is added."], ["Because under the law a loan for sustainable installations may never run longer than ten years", "No such statutory maximum term exists; this is about sensible financing."], ["Because the interest deduction lapses as soon as the installations have been depreciated", "The interest deduction depends on the rules for owner-occupied home debt, not on depreciation."], ["Because otherwise the lender may remove the installations at the end", "The lender has a mortgage right on the home and no right to remove installations."]], "1i.1"],
["What must a mortgage adviser provide a client before the service about his services and costs?", [["The nature of the services and the costs", "The client must know in advance what the adviser does, for whom and what it costs, in order to make a conscious choice."], ["Nothing; costs are reported only afterwards with the invoice", "Cost information must in fact be given in advance, so that the client knows where he stands."], ["Only the lender's ESIS", "The ESIS concerns the credit, not the adviser's services and costs."], ["An overview of the commission he receives from the lender", "A commission ban applies to mortgages; the client pays the adviser directly."]], "1a.6"],
["Which diploma must an adviser who advises consumers on mortgage credit have in any case?", [["The Wft Mortgage Credit diploma", "Professional competence requires the appropriate Wft diploma and keeping knowledge up to date through PE (permanent education)."], ["A registration as a valuer in the NRVT", "A valuer registration concerns valuing homes, not mortgage advice."], ["A notarial certificate", "Notaries have their own training; that is not a competence requirement for advisers."], ["The Wft Basic diploma alone is sufficient", "Basic is a component, but for mortgage advice the Mortgage Credit diploma is also required."]], "1b.4"],
["A client is dissatisfied with the mortgage advice and cannot reach agreement with his adviser. Where can he turn with a complaint?", [["To Kifid (Dutch Financial Services Complaints Institute)", "A Wft adviser must be affiliated with a recognised dispute resolution body; for financial services that is Kifid."], ["To FIU-Nederland", "FIU-Nederland receives reports of unusual transactions, not complaints from consumers."], ["To the Land Registry", "The Land Registry keeps registers and does not handle complaints about advice."], ["To Stichting WEW", "Stichting WEW provides NHG (National Mortgage Guarantee); it does not decide on disputes between client and adviser."]], "1a.3"],
["May a consumer take out a mortgage without advice (execution only)?", [["Yes, but the creditworthiness test continues to apply", "Even without advice, the obligation to prevent over-lending remains with the lender."], ["No, mortgage advice is legally mandatory for consumers", "The law does not require advice; a consumer may choose without advice."], ["Yes, and then the creditworthiness test also lapses", "The test always applies, with or without advice."], ["Only if the mortgage is taken out with NHG (National Mortgage Guarantee)", "Execution only does not depend on NHG."]], "1b.4"],
["An employee receives a fixed, unconditional thirteenth month every year. How does it count towards the test income?", [["It counts in full as fixed income", "Fixed and unconditional components such as a fixed year-end payment form part of structural income."], ["It does not count, because it is paid only once a year", "The moment of payment is not decisive; holiday allowance is also paid once a year and counts."], ["It counts only if the employer has a bonus scheme for it", "A fixed thirteenth month is not a bonus; a scheme is not needed if it is unconditional."], ["It counts, but only for half", "The test knows no halving; a fixed income component counts in full."]], "2c.2"],
["Niels (39) works as a sales manager at a wholesaler in Venlo. In addition to his fixed salary of €58,000, in recent years he received a performance bonus, which is set anew each year and is not guaranteed. He wants to move to a larger home and hopes the bonus will count. On his employer's statement the bonus is shown as variable. How do lenders usually deal with this?", [["A variable, non-guaranteed bonus does not in principle count as fixed income", "Only fixed and structural income components in principle count; an uncertain bonus does not."], ["The bonus counts in full, because it has been paid every year in recent years", "Payment in the past gives no certainty for the future."], ["The bonus counts double to absorb the uncertainty of his salary", "Counting double does not exist and would in fact increase the risk."], ["The bonus reduces his test income, because he pays more tax on it", "The tax on a bonus does not reduce the gross test income."]], "2c.2"],
["For a retired applicant: what normally forms the test income?", [["The AOW (state pension) benefit and the pension payments", "After the AOW (state pension) age, structural income consists of AOW (state pension) and (supplementary) pension; separate percentages apply to it."], ["The last salary earned before retirement", "That salary no longer exists; the test looks at current structural income."], ["The assets in box 3 divided by thirty", "Assets can be weighed in the advice, but are not the standard test income."], ["Only the supplementary pension, without AOW (state pension)", "The AOW (state pension) is a fixed basic income and counts towards the test income."]], "1i.4"],
["A client has a permanent contract with a probationary period that is still running. Why is this relevant to the mortgage application?", [["The employment can then easily be terminated", "Many lenders want the probationary period to be over or ask for an additional statement from the employer."], ["During the probationary period the salary is tax-free", "Payroll tax is also withheld on salary during the probationary period."], ["A probationary period means the contract is temporary", "A permanent contract remains a permanent contract, even with a probationary period."], ["During the probationary period only the net salary counts", "The test calculates with gross income; the probationary period does not change that."]], "2c.2"],
["Since 2024, how does a student debt with DUO (Education Executive Agency) count in the lending standards?", [["On the basis of the actual monthly payment on the student debt", "Since 2024 the TRHK has weighed the current monthly repayment instead of a percentage of the original debt."], ["On the basis of a fixed percentage of the original student debt", "That was the method until 2024; now the actual monthly payment is the starting point."], ["Not at all, because DUO debts are not registered with the BKR (Dutch credit registration bureau)", "Even though it is not at the BKR, the student debt does count; the client must declare it."], ["Only if the client has arrears with DUO", "Even without arrears, the student debt is an obligation that counts."]], "1i.4"],
["An unmarried cohabiting client without children dies. Why can his partner as a rule not count on an Anw benefit?", [["Only with a child under 18 or own incapacity for work", "Without a young child or incapacity for work, a partner born after 1949 has no right to Anw."], ["The Anw applies only to married partners", "Cohabitants with a joint household can also be entitled; the conditions lie in children and incapacity for work."], ["The Anw is paid only if there is a mortgage with NHG (National Mortgage Guarantee)", "The Anw is a national insurance and is independent of the mortgage."], ["The Anw benefit always goes directly to the lender", "The Anw is paid to the surviving dependant himself, if there is entitlement."]], "1a.4"],
["Jordy (32) and Anna (30) live together unmarried and are buying a home in Enschede. Each earns about half of the household income. They both want to insure the other's life with term life insurance. Their adviser recommends taking out the policies crosswise. Why does he advise that?", [["So that no inheritance tax is levied on the payout on death", "If the partner is himself the policyholder, pays the premium and is the beneficiary, the payout does not fall under inheritance tax."], ["So that the premium on both policies becomes deductible in box 1", "The premium on term life insurance is not deductible, not even crosswise."], ["So that both partners receive a payout on one death", "On one death only the policy on the life of the deceased pays out."], ["So that the payout automatically repays the mortgage via the notary", "Crosswise insurance regulates the tax, not repayment via the notary."]], "1i.6"],
["Hamza (35) and Lieke (34) take out an annuity mortgage of €320,000 for their first home in Den Bosch. Lieke earns the largest part of the income. They want Hamza to be able to keep paying for the home if Lieke dies. They do not want to pay premium for cover that they will no longer need later. Which form of cover of the term life insurance best matches the course of their debt?", [["An annuity-decreasing cover that falls with their remaining debt", "With an annuity mortgage the debt falls slowly at first and faster later; an annuity-decreasing cover follows that course."], ["A constant cover of €320,000 over the whole term", "A constant cover is more expensive and runs further and further ahead of the falling debt."], ["A linearly decreasing cover that in fact falls quickly at the start", "Linear decrease suits a linear mortgage; with an annuity the cover would fall too quickly at the start."], ["A rising cover that grows with inflation", "The debt does not rise, so a rising cover does not match the course of the debt."]], "1g.2"],
["What is meant by the WGA gap in the event of incapacity for work?", [["A fall in income after the wage-related WGA benefit", "Someone who does not sufficiently use his remaining earning capacity falls back on a benefit based on the minimum wage, which can threaten the housing costs."], ["The two-year period of continued payment of wages by the employer", "Continued payment of wages precedes the WIA and is not a gap in income."], ["The difference between gross and net WGA benefit", "That is an ordinary tax effect, not what is meant by the WGA gap."], ["The part of the salary above the maximum daily wage", "That is the WIA excess, a different risk from the WGA gap."]], "1a.4"],
["An employee becomes unemployed and receives WW (unemployment benefit). What percentage of the (capped) daily wage does he receive?", [["75% for the first two months, then 70%", "The WW starts at 75% and falls after two months to 70% of the daily wage, up to the maximum daily wage."], ["100% of the last wage earned for the whole duration", "The WW replaces wages only partly; full replacement does not exist."], ["70% for the first two months, then 75%", "The order is the other way round: the benefit falls after two months."], ["Always 50%, regardless of the duration", "The percentage is higher and changes after two months."]], "1a.4"],
["Which insurance pays out an amount monthly to cover the housing costs if the client becomes incapacitated for work or unemployed?", [["Housing costs insurance (woonlastenverzekering)", "It covers the monthly costs for a limited period in the event of incapacity for work and/or unemployment."], ["Buildings insurance", "Buildings insurance covers damage to the home, not loss of income."], ["Term life insurance", "Term life insurance (ORV) pays out only on the death of the insured."], ["Legal expenses insurance", "Legal expenses insurance helps with legal disputes, not with paying monthly costs."]], "1g.1"],
["A client buys a home with a mortgage of 100% of the market value. A few years later house prices fall. Which risk arises?", [["On sale a residual debt may arise", "With negative equity the sale proceeds do not cover the debt; this also limits the possibility of moving."], ["The interest rate is automatically raised to the level of a consumer credit", "A fall in value does not automatically lead to a consumer-credit interest rate; at most a risk surcharge may later turn out higher."], ["The mortgage immediately becomes repayable", "A fall in prices is not a ground for calling in the loan as long as the client meets his payments."], ["The interest deduction lapses, because the loan is higher than the value of the home", "A fall in value has no effect on the tax status of the owner-occupied home debt."]], "1e.9"],
["Jolanda (49) and Frank (51) have bought a new home in Amersfoort, to be delivered in three months. Their current home in Leusden has only recently been put up for sale, but there is no buyer yet. They want to buy the new home anyway, because it fits perfectly. The bank is willing to let both mortgages run side by side for a time. Which risk should the adviser in any case discuss with them?", [["Double housing costs as long as the old home has not been sold", "As long as the old home has not been sold, they pay housing costs twice; the adviser must check whether they can bear that."], ["The loss of their right to NHG (National Mortgage Guarantee) for the new home", "An unsold old home does not automatically exclude NHG for the new home."], ["Higher transfer tax on the old home", "The seller does not pay transfer tax; it is for the buyer."], ["The lapsing of the statutory cooling-off period for the new home", "The cooling-off period is separate from the sale of the old home."]], "1e.11"],
["Why does foundation risk deserve attention in the mortgage advice, for example for older homes in peat areas?", [["Repair can be expensive and affect the value of the home", "Foundation problems can lead to high repair costs, a fall in value and problems on refinancing."], ["It automatically lowers the mortgage interest rate via the risk class", "Foundation risk does not lead to a lower interest rate; it in fact increases the risk."], ["It determines the level of the national NHG (National Mortgage Guarantee) cost limit", "The NHG cost limit is set nationally and is independent of individual homes."], ["It is relevant only for new-build homes", "Foundation problems in fact arise with older homes on wooden piles or on shallow foundations."]], "1f.1"],
["Stijn (35) is a teacher and is buying an apartment in Zwolle on his own with a fully annuity mortgage. He has used all his savings for the purchase costs and furnishing. His car is old and his central heating boiler will soon need replacing. He assumes he can pay for unexpected costs from his salary. What is an important point of attention in the advice?", [["The importance of building up a financial buffer for unexpected expenses", "Without a buffer a setback can lead directly to payment problems; the adviser should discuss this."], ["That he had better make the mortgage interest-only in order to build up assets faster", "An interest-only loan is not owner-occupied home debt and increases the risk at the end."], ["That his interest deduction lapses after ten years and his costs then rise", "The interest deduction runs for a maximum of thirty years, not ten."], ["That he is obliged to take out an investment insurance alongside the mortgage", "An investment insurance is never mandatory alongside an annuity mortgage."]], "1d.2"],
["In 2011, adviser Pieter advised Marco (40) and Ilona (38) to take a fully interest-only mortgage. His file does not state that he discussed the risks of this with them. It now turns out that they cannot refinance the debt at the end of the term, and they lodge a complaint with Kifid (Dutch Financial Services Complaints Institute). They claim that they were never made aware of the risks. What weighs heavily in assessing Pieter's liability?", [["Whether Pieter can show he discussed the risks; unrecorded, that is hard", "The adviser must be able to demonstrate his duty of care; an incomplete file usually counts against him."], ["Only whether the lender approved the mortgage at the time", "Acceptance by the lender does not release the adviser from his own duty of care."], ["Whether the clients signed the advice report, regardless of its content", "A signature says little if it is not apparent that the risks were explained comprehensibly."], ["Nothing, because after signing the offer the client is responsible himself", "The adviser remains responsible for the quality of his advice."]], "1c.1"],
["Why must a mortgage adviser map out the client's risk appetite properly?", [["Because it helps determine which fixed-rate period, repayment form and insurance policies are suitable", "Suitable advice matches the extent to which the client wants and is able to bear financial risks."], ["Because the lender tailors the interest rate to the client's risk appetite", "The interest rate depends on, among other things, the fixed-rate period and the LTV, not on risk attitude."], ["Because a client with little risk appetite may legally borrow less", "No such statutory standard exists; the lending standards are based on income and the value of the home."], ["Because risk appetite determines the level of the test income", "The test income follows from income, not from risk attitude."]], "1d.1"],
["Adviser Monique is guiding Dewi (29), who wants to buy an apartment in Utrecht. Dewi submits an employer's statement showing a salary of €62,000, but her payslips and the UWV (Employee Insurance Agency) data show a clearly lower amount. The signature on the statement also seems to resemble Dewi's own. Dewi wants to submit the application quickly. What should Monique do?", [["Not submit it, investigate the discrepancy and report the signal per the fraud procedure", "A possibly forged document is a fraud signal that the adviser must follow up herself; she may not forward it unseen."], ["Simply submit the application, because the lender itself is responsible for checking documents", "The adviser has her own responsibility; knowingly submitting possibly false documents is not permitted."], ["Change the salary on the employer's statement herself to the lower amount", "An adviser may never change documents of the client or employer herself."], ["Submit the application with only the payslips and withhold the statement", "Withholding does not resolve the fraud signal; the signal must be followed up."]], "4a.1"],
["A client with his own private limited company (bv) wants a mortgage and is considering borrowing money from his bv and paying out dividend. The adviser has little knowledge of the tax rules for a bv. What is the right attitude?", [["Engage or refer to a tax specialist for the part that falls outside his expertise", "An adviser knows the limits of his knowledge and refers on if that is in the client's interest."], ["Make an estimate himself, because with his Wft Mortgage Credit diploma he may also advise on tax", "The diploma does not cover specialist tax questions about a bv; advising outside his expertise harms the client."], ["Leave the tax questions out of the advice without discussing this with the client", "The client must know which part has not been investigated and where he can turn."], ["Advise the client not to take out a mortgage as long as he has a bv", "A bv is no obstacle to a mortgage; it only requires specialist knowledge."]], "4a.2"],
["A client wants to have a heat pump installed, which he finances with his mortgage. How can the loan part be treated for tax purposes?", [["As owner-occupied home debt, because it improves the home", "Expenditure on improving the owner-occupied home can be owner-occupied home debt if the repayment requirement is met."], ["As a box 3 debt, because a heat pump is a movable asset", "A permanently installed system improves the home and can fall within the owner-occupied home debt."], ["As consumer credit without tax consequences", "Financing through the mortgage for home improvement can in fact be owner-occupied home debt."], ["The interest is deductible twice because of the sustainability", "There is no double deduction for sustainable investments."]], "1a.1"],
["A client takes out a mortgage in a foreign currency. What does the Mortgage Credit Directive (MCD) regulate on this?", [["Safeguards against exchange rate risk, such as conversion", "Foreign-currency loans can become much more expensive with exchange rate fluctuations; the MCD therefore requires safeguards."], ["Foreign-currency loans are prohibited throughout the EU", "The MCD does not prohibit them, but sets requirements for protection and information."], ["The lender always bears the full exchange rate loss itself", "The risk in principle lies with the consumer; the MCD limits that with safeguards."], ["Foreign-currency loans fall outside the directive", "They in fact fall under it, with additional rules."]], "1a.3"],
["What does the Mortgage Credit Directive (MCD) expect of lenders when a consumer has payment arrears?", [["Forbearance and attempts at a solution before enforcement", "The directive asks providers first to look for solutions, such as a payment arrangement, before they enforce."], ["Enforce immediately to prevent further arrears", "Enforcing immediately is contrary to the idea of forbearance in the directive."], ["Double the interest rate until the arrears have been made up", "Doubling a penalty rate does not help the consumer and does not fit the directive."], ["Report the arrears to FIU-Nederland", "A payment arrear is not an unusual transaction within the meaning of the Wwft."]], "1j.2"],
["When may a mortgage adviser call himself 'independent'?", [["If he compares widely and receives no payment from providers", "This requirement comes from the Mortgage Credit Directive: independence requires a wide market comparison and no remuneration from providers."], ["If he is not employed by any lender", "Not being employed is not enough; he must also compare sufficient products."], ["If he has a sign saying 'independent' on the front of his office", "The term is legally protected and requires more than a self-declaration."], ["If he works only with the three largest banks", "Three providers is not a sufficient number of products for a wide market comparison."]], "1b.4"],
["An advertisement for mortgages states an interest rate. What do the rules under the Mortgage Credit Directive require?", [["Standard information with a representative example", "Anyone who states an interest rate or costs in advertising must also give information such as the APRC (JKP) with a representative example."], ["That the AFM has approved the advertisement in advance", "The AFM does not approve advertising in advance; it supervises after the fact."], ["That the interest rate remains valid for at least a year", "No such requirement exists for advertising."], ["That the advertisement may appear only online", "There is no restriction to online advertising."]], "1a.3"],
["Rachid (42) and Hanna (40) have moved to their new home in Leiden. Their previous home in The Hague has already been for sale for a year. To limit the double costs, they are letting it temporarily under a permit pursuant to the Vacancy Act (Leegstandwet) and with the lender's consent. The rent covers a large part of the interest. What is the tax consequence for the period of letting?", [["In that period the old home and its debt fall in box 3, not in box 1", "A let home is no longer an empty owner-occupied home; during the letting, home and debt fall in box 3."], ["The interest remains fully deductible, because the home is still for sale", "The scheme for empty homes does not apply if the home is let."], ["The rental income is taxed in box 1 and the interest remains deductible there", "Letting does not fall under the owner-occupied home regime in box 1."], ["The home falls in box 2, because it yields income from letting", "Box 2 concerns a substantial interest in a company, not the letting of a home."]], "1e.11"],
["Joyce (33) and Ramon (35) are advised to choose a fixed-rate period of twenty years, because they have little financial room. Ramon nevertheless wants a variable interest rate, because it is lower at present. The adviser explains the risks of an interest rate rise, but they stick to their choice. They want to proceed with the application as it stands. What should the adviser do?", [["Explain the consequences once more and record the deviation from his advice with their reasons", "A client may deviate from the advice; the adviser then records that and why the client deviates and which consequences were discussed."], ["Adjust his advice so that it matches Ramon's choice exactly", "The advice must remain suitable; adjusting it to the client's wish without justification is not genuine advice."], ["Refuse to guide the application further, because deviating from advice is not legally permitted", "Deviating from the advice is permitted; the law does not prohibit it."], ["Carry out the choice without recording anything, because the client decided himself", "Precisely in the case of deviation, recording in the file is important."]], "3c.4"],
["A client applying for a mortgage turns out to be a politically exposed person (PEP). What applies?", [["Enhanced customer due diligence, incl. the origin of the assets", "With a PEP the risk of corruption is higher; the institution must take additional measures."], ["The application must be refused", "Providing services to a PEP is permitted, provided enhanced measures are applied."], ["Simplified customer due diligence is sufficient", "A PEP in fact entails a higher risk, so simplified investigation does not fit."], ["No customer due diligence is needed because of the public office", "A public office does not reduce the risk; customer due diligence remains mandatory."]], "1a.3"],
["Wouter (37) and Kirsten (36) have a binding mortgage offer for a home in Alkmaar and the transfer is in four weeks. Wouter hears from his employer that his position is being eliminated and that he will be dismissed in three months. The application is based on his current income. They ask their adviser whether they have to report this. What is correct?", [["Report the dismissal to the lender, because the offer is based on the current income", "A material change during the application process must be reported; the lender then reassesses and the adviser discusses the consequences."], ["Report nothing, because the offer is already binding and the lender may no longer withdraw it", "Concealing a material change is contrary to the terms of the offer and to the duty of care."], ["Report it only if the dismissal has not been withdrawn after the transfer", "Waiting until after the transfer deprives the lender of the chance to assess the change."], ["Dissolve the purchase immediately by invoking the statutory cooling-off period", "The three-day cooling-off period has long since expired and is separate from a dismissal."]], "2e.3"],
["Linda (46) is single and works as a shop manager in Purmerend. Because of a long illness and a temporarily lower income she is two months behind with her mortgage payments. She is ashamed and has left letters from the bank unopened. She asks her adviser what she should do now. What is the best advice?", [["Contact the lender as soon as possible to discuss a (temporary) solution", "The sooner the client makes contact, the more options there are, such as a payment arrangement; this prevents further escalation."], ["Wait until the bank comes up with a solution itself, because it is legally obliged to help her", "Waiting increases the arrears and the chance of further measures."], ["Quickly take out a personal loan to make up the arrears in one go", "New debts usually make the problem bigger."], ["Put the home up for sale immediately to prevent enforcement by the bank", "Sale is relevant only if other solutions do not work; the conversation with the bank must take place first."]], "3f.1"],
["Iris (27) and Joep (28) rent an apartment in Utrecht and are wondering whether to buy a home. Joep expects to move abroad for work in two to three years. They have little savings and would have to pay the purchase costs largely themselves. A friend says buying is always better than renting. What is an important consideration in their situation?", [["The expected length of stay, because one-off purchase costs weigh heavily over a short stay", "Purchase costs and selling costs are recouped only over a longer period; with a short stay, renting may be more advantageous."], ["Buying is always more advantageous, because rent is money thrown away", "Whether buying is more advantageous depends on length of stay, costs, interest rate and price development."], ["Renting is always more advantageous, because a tenant pays no maintenance", "Renting is not always more advantageous either; the weighing depends on the situation."], ["The amount of rent allowance they will continue to receive after buying a home of their own", "After buying a home there is no entitlement to rent allowance."]], "1b.1"],
["In addition to the Wwft, what must a financial undertaking check under the Sanctions Act 1977?", [["Whether clients are on sanctions lists", "In the event of a match, funds must be frozen and no services may be provided."], ["Whether clients have a Certificate of Conduct (VOG)", "A VOG is requested by the employer of employees, not of clients."], ["Whether clients have a BKR (Dutch credit registration bureau) registration", "BKR checking belongs to lending, not to the Sanctions Act."], ["Whether clients have drawn up a will", "That is not part of the Sanctions Act."]], "1a.3"],
["A client does not want to show proof of identity for the mortgage application. What must the Wwft institution do?", [["Not enter into the relationship and not process the application", "Without established and verified identity the institution may not enter into a relationship and must consider reporting."], ["Process the application and make up the identification later", "Identification must in principle take place beforehand; without it the relationship cannot start."], ["Settle for a copy of an energy bill", "An energy bill does not prove identity."], ["Refer the client to the notary, who takes over the identification", "The institution must itself comply with its duty."]], "1a.3"],
["Ger (55) and Petra (53) live in their own home in Zeist. Their daughter Romy (19) is going to study in Utrecht and they buy a small apartment for her. Romy will live there; Ger and Petra remain in their own house. They are the only buyers on the purchase deed. Which transfer tax rate applies to Ger and Petra?", [["The higher rate, because they will not live in it as their main residence", "The reduced rate and the first-time buyer exemption apply only to a buyer who will occupy the home himself as his main residence."], ["The reduced rate, because a family member of theirs will live in the home", "Occupation by a child does not count as owner-occupation by the buyer."], ["The first-time buyer exemption, because Romy is under 35", "The exemption is assessed for the buyer, not for the occupier."], ["No transfer tax, because it concerns student housing", "There is no exemption for student housing by parents."]], "1a.1"],
["A client has a bridging loan on his old home, which has been for sale longer than expected. What is an important risk?", [["The bridging loan expires before the old home has been sold", "Bridging loans have a limited term; if the sale does not materialise, costs and uncertainty build up."], ["The bridging loan is automatically converted into a starter loan", "A starter loan is a separate scheme and does not arise from a bridging loan."], ["The interest deduction on the new home lapses immediately", "The deduction for the new home simply remains."], ["The new home must be given back to the seller", "The purchase of the new home is fixed; a slow sale does not undo it."]], "1e.3"],
["A client asks whether the lender may raise his mortgage interest rate during a running fixed-rate period. What is correct in principle?", [["No, during the fixed-rate period the agreed interest rate is fixed", "That is exactly the certainty the client buys with a fixed-rate period."], ["Yes, if the market interest rate rises the bank may adjust the rate immediately", "That applies to a variable interest rate, not to a fixed rate."], ["Yes, but only once a year by a maximum of one percentage point", "No such rule exists for fixed rates."], ["Yes, if the AFM test rate rises", "The test rate is a test figure and does not change the contract rate."]], "1e.2"],
["A client has two loan parts: an annuity part and a linear part. What is correct about the tax repayment requirement?", [["Both loan parts meet the repayment requirement", "The repayment requirement calls for at least annuity repayment within 30 years; linear repays faster and therefore also meets it."], ["Only the annuity part meets the repayment requirement", "Linear repayment also meets it, because it is faster than annuity."], ["Only the linear part meets it, because annuity repays too slowly", "Annuity within 30 years is precisely the minimum requirement."], ["Neither, because combinations are not permitted", "Combinations of loan parts are perfectly possible."]], "1a.1"],
["A client wants to let his home temporarily during a period of work abroad. What must he do under the usual mortgage terms?", [["Ask his lender in advance for permission to let", "Letting affects the lender's security; the terms and the rental clause therefore require prior permission."], ["Nothing; letting an owner-occupied home is always freely permitted", "Mortgage terms restrict letting without permission, precisely to protect the value of the collateral."], ["Only report the letting to the municipality where the home is located", "A notification to the municipality does not replace the lender's permission."], ["First refinance the mortgage in full to another lender", "Refinancing is not necessary; the client must ask his current lender for permission."]], "1e.11"],
["A client lives in a home on leasehold land and pays ground rent (canon) annually. How is that ground rent treated in income tax?", [["It is deductible in box 1 as costs of the owner-occupied home", "In addition to mortgage interest, periodic leasehold payments for the owner-occupied home can be deducted in box 1."], ["The ground rent is not deductible, because it is a form of rent", "For tax purposes the periodic ground rent for the owner-occupied home in fact counts as deductible costs, like interest."], ["The ground rent increases the notional rental value by the same amount", "The ground rent has no effect on the notional rental value; that remains a percentage of the WOZ value."], ["The ground rent falls as a debt in the leaseholder's box 3", "A periodic payment is not a debt; the ground rent is a deduction in box 1."]], "1h.4"],
["A housing association sells a home at a discount on the market value, with the agreement that the association buys the home back on sale. What is characteristic of such a purchase arrangement?", [["On sale the buyer shares the development in value with the association, which buys the home back", "In return for the discount, profit or loss on buy-back is shared according to an agreed split."], ["The buyer pays no mortgage interest as long as he occupies the home", "The buyer simply finances the reduced purchase price with a mortgage and pays interest on it."], ["On sale the buyer may sell the home freely to any third party at the then prevailing market price", "This arrangement in fact involves a buy-back scheme with the association."], ["The association remains the owner and the buyer pays only rent", "The buyer becomes the legal owner; that distinguishes this arrangement from renting."]], "1b.6"]
];
